const DB='MAGHRABY_STORE_FRESH_V8',VER=3;
const ACCOUNTS=[['drawer','الدرج'],['wallet','المحفظة الإلكترونية'],['instapay','InstaPay']];
const stores=['products','sales','repairs','cash','expenses','purchases','customers','staff','invoices','days','audit','settings','transfers','returns','stockMoves','deposits'];
let db,state={page:'dashboard',cat:'',cart:[],discount:0,cartNote:'',saleCustomer:'',saleAccount:'drawer',lastInvoice:null,q:'',globalQ:''};
const NAV=[
['dashboard','⌂','لوحة التحكم'],['sale','▣','المبيعات والكاشير'],['repair','⌁','الصيانة والمتابعة'],
['inventory','◇','المخزون والمنتجات'],['purchases','＋','المشتريات والتوريد'],['customers','◉','العملاء'],
['cash','₤','الخزنة والحركات'],['expenses','−','مصروفات المحل'],['staff','⚒','الفنيون والسلف'],
['needs','≡','الاحتياجات'],['returns','↶','المرتجعات'],['reports','▥','الربح والتقارير'],['invoices','▤','الفواتير'],['settings','⚙','الإعدادات'],['backup','⇩','النسخ الاحتياطي']
];
const seed=[];
const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),today=()=>now().slice(0,10);
const money=n=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:0}).format(Number(n)||0)+' ج';
const accountName=a=>(ACCOUNTS.find(x=>x[0]===a)||ACCOUNTS[0])[1];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function normalizeCash(x){return {...x,account:x.account||'drawer'};}
async function cashAll(){return (await req('cash')).map(normalizeCash)}
async function dayRecord(date){return (await req('days')).find(x=>x.date===date)}
async function openingBalance(date,account){let days=await req('days');let prev=days.filter(x=>x.date<date).sort((a,b)=>b.date.localeCompare(a.date))[0];if(prev){if(account==='drawer')return Number(prev.drawerCounted??prev.counted??0);return Number(prev[account+'Counted']??0)}let settings=await req('settings');let init=settings.find(x=>x.id==='finance');return Number(init?.[account+'Opening']??0)}
async function balanceFor(date,account){let c=(await cashAll()).filter(x=>x.date.slice(0,10)===date&&x.account===account);let opening=await openingBalance(date,account),inc=c.filter(x=>x.type==='in').reduce((a,x)=>a+Number(x.amount||0),0),out=c.filter(x=>x.type==='out').reduce((a,x)=>a+Number(x.amount||0),0);return {opening,inc,out,expected:opening+inc-out}}
async function currentDayOpen(){const d=await dayRecord(today());return !!(d && !d.closedAt && d.openedAt)}
async function requireOpenDay(){if(await currentDayOpen())return true;toast('افتح اليوم أولًا من زر «فتح اليوم» قبل تسجيل أي عملية');return false}
async function openDay(){const d=today(),existing=await dayRecord(d);if(existing?.closedAt)return toast('اليوم مقفول بالفعل. افتح يومًا جديدًا في اليوم التالي.');if(existing?.openedAt)return toast('اليوم مفتوح بالفعل');const B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));const x={...(existing||{}),id:d,date:d,openedAt:now(),status:'open'};ACCOUNTS.forEach((a,i)=>x[a[0]+'Opening']=B[i].opening);await put('days',x);toast('تم فتح اليوم — رصيد البداية تم ترحيله تلقائيًا');updateDayButton();render()}
async function updateDayButton(){const b=$('closeToday');if(!b)return;const d=await dayRecord(today());if(!d||(!d.closedAt&&!d.openedAt)){b.textContent='فتح اليوم';b.className='btn mint';b.onclick=openDay;b.disabled=false}else if(d.closedAt){b.textContent='اليوم مقفول';b.className='btn dark';b.onclick=()=>toast('اليوم مقفول بالفعل');b.disabled=true}else{b.textContent='إقفال اليوم';b.className='btn dark';b.onclick=closeDay;b.disabled=false}}

function accountOptions(selected='drawer'){return ACCOUNTS.map(([id,n])=>`<option value="${id}" ${selected===id?'selected':''}>${n}</option>`).join('')}
function whatsapp(phone,text){let p=String(phone||'').replace(/[^0-9]/g,'');if(p.startsWith('0'))p='20'+p.slice(1);if(!p)return toast('رقم العميل غير صالح للواتساب');window.open('https://wa.me/'+p+'?text='+encodeURIComponent(text),'_blank','noopener');}
const val=id=>$(id)?.value?.trim()||'';
function req(s){return new Promise((res,rej)=>{let q=db.transaction(s).objectStore(s).getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}
function put(s,x){return new Promise((res,rej)=>{let q=db.transaction(s,'readwrite').objectStore(s).put(x);q.onsuccess=()=>res(x);q.onerror=()=>rej(q.error)})}
async function boot(){await new Promise((res,rej)=>{let r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{db=r.result;stores.forEach(s=>{if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'})})};r.onsuccess=()=>{db=r.result;res()};r.onerror=()=>rej(r.error)});bind();clock();render();updateDayButton()}
function bind(){
  $('menu').onclick=()=> $('sidebar').classList.toggle('open');
  $('backup').onclick=backup;
  $('closeToday').onclick=()=>dayToggle();updateDayButton();
  let gs=$('globalSearch');
  if(gs){
    gs.onkeydown=async e=>{
      if(e.key==='Enter'){
        let q=gs.value.trim();
        if(!q)return;
        let [ps,cs]=await Promise.all([req('products'),req('customers')]);
        let p=ps.find(x=>x.name.includes(q));
        let c=cs.find(x=>x.name.includes(q)||String(x.phone||'').includes(q));
        if(p){state.page='inventory';state.q=q}else if(c){state.page='customers';state.q=q}else{state.page='sale';state.q=q}
        render();
      }
    };
    window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();gs.focus()}});
  }
  document.addEventListener('click',e=>{
    let b=e.target.closest('[data-page]');
    if(b){state.page=b.dataset.page;state.cat='';render();$('sidebar').classList.remove('open')}
  });
}
async function dayToggle(){const d=await dayRecord(today());if(!d)openDay();else if(d.closedAt)toast('اليوم مقفول بالفعل');else closeDay()}
function clock(){setInterval(()=>{let d=new Date();$('date').textContent=d.toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('time').textContent=d.toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit',second:'2-digit'})},500)}
function nav(){ $('nav').innerHTML=NAV.map(n=>`<button class="nav-item ${state.page===n[0]?'active':''}" data-page="${n[0]}"><span class="nav-icon">${n[1]}</span><span class="nav-label">${n[2]}</span><span class="nav-arrow">‹</span></button>`).join('');$('title').textContent=(NAV.find(n=>n[0]===state.page)||NAV[0])[2]}
async function render(){nav();let v=$('view');({dashboard,sale,repair,inventory,purchases,customers,cash,expenses,staff,needs,returns,reports,invoices,settings,backupPage}[state.page]||dashboard)(v)}
function stat(label,n,sub=''){return `<div class="card stat"><div class="label">${label}</div><div class="num">${typeof n==='number'?money(n):n}</div><div class="sub">${sub}</div></div>`}
async function dashboard(v){let [s,r,e,c,p]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('products')]),d=today(),sd=s.filter(x=>x.date.slice(0,10)===d),ed=e.filter(x=>x.date.slice(0,10)===d),pending=r.filter(x=>x.status!=='تم التسليم'),low=p.filter(x=>x.type!=='service'&&x.stock<=x.min&&x.min>0),drawer=await balanceFor(d,'drawer'),wallet=await balanceFor(d,'wallet'),instapay=await balanceFor(d,'instapay'),cogs=sd.reduce((a,x)=>a+x.items.reduce((z,i)=>z+i.cost*i.qty,0),0),salesTotal=sd.reduce((a,x)=>a+x.total,0),profit=salesTotal-cogs-ed.reduce((a,x)=>a+x.amount,0);
let rawCash=await cashAll();let todayCash=rawCash.filter(x=>x.date.slice(0,10)===d&&!x.transfer);let inc=todayCash.filter(x=>x.type==='in').reduce((a,x)=>a+Number(x.amount||0),0),out=todayCash.filter(x=>x.type==='out').reduce((a,x)=>a+Number(x.amount||0),0);
v.innerHTML=`<div class="grid stats">${stat('مبيعات اليوم',salesTotal,'بعد الخصومات')}${stat('دخل الخزنة',inc,'كل حركات الداخل')}${stat('خرج الخزنة',out,'كل حركات الخارج')}${stat('المتوقع في الدرج',drawer.expected,'رصيد أمس + الداخل − الخارج')}${stat('المحفظة',wallet.expected,'رصيد جارٍ')}${stat('InstaPay',instapay.expected,'رصيد جارٍ')}${stat('ربح تقريبي',profit,'مبيعات − تكلفة − مصروفات')}${stat('أجهزة معلقة',pending.length,'جهاز — تحتاج متابعة')}</div>
<div class="hero card"><div><span class="eyebrow">MAGHRABY STORE • مركز التشغيل</span><h2>جاهز تبدأ شغل اليوم؟</h2><p>أضف المنتجات والخدمات أولًا، وبعدها النظام هيبني لك المبيعات والمخزون والتقارير تلقائيًا.</p></div><button class="btn primary hero-btn" data-page="inventory">＋ ابدأ بإضافة أول منتج</button></div><div class="section"><h2>مركز العمل</h2></div><div class="grid quick"><button data-page="sale">🛒<b>بيع جديد</b><small>سلة + خصم + ملاحظات + فاتورة</small></button><button data-page="repair">🔧<b>استلام صيانة</b><small>الجهاز والعطل والمدة والحالة</small></button><button data-page="cash">💵<b>حركة خزنة</b><small>دخل / خرج / سلفة / مصروف</small></button><button data-page="purchases">📦<b>شراء بضاعة</b><small>يزود المخزون ويحسب التكلفة</small></button><button data-page="reports">🔒<b>إقفال اليوم</b><small>عد الدرج واعرف الفرق</small></button></div>
<div class="grid two"><div><div class="section"><h2>⚠ يحتاج انتباه</h2></div><div class="card">${low.length?low.map(p=>`<div class="kpi"><span>📦 ${p.name}<small> — الموجود ${p.stock}</small></span><b class="negative">اطلب الآن</b></div>`).join(''):'<div class="empty">المخزون الأساسي جيد 🎉</div>'}</div></div><div><div class="section"><h2>🔧 الصيانة</h2></div><div class="card">${pending.slice(0,5).map(r=>`<div class="kpi"><span><b>${r.customer}</b> — ${r.device}<small> ${r.fault}</small></span><b class="negative">${Math.floor((Date.now()-new Date(r.date))/86400000)} يوم</b></div>`).join('')||'<div class="empty">لا توجد أجهزة معلقة</div>'}</div></div></div>`}
async function sale(v){let [ps,cs]=await Promise.all([req('products'),req('customers')]);let cats=[...new Set(ps.map(p=>p.cat).filter(Boolean))];let q=(state.q||'').toLowerCase();let arr=ps.filter(p=>p.active!==false&&(!state.cat||p.cat===state.cat)&&p.name.toLowerCase().includes(q));v.innerHTML=`
<div class="page-head"><div><span class="eyebrow">POS • MAGHRABY STORE</span><h2>المبيعات والكاشير</h2><p>بيع أسرع، عدد أقل من الضغطات، وحركة مالية محفوظة تلقائيًا.</p></div><div class="head-actions"><button class="btn ghost" onclick="clearCart()">مسح السلة</button><button class="btn primary" onclick="customerNew()">＋ عميل جديد</button></div></div>
<div class="pos-layout"><section class="card pos-products"><div class="toolbar"><div class="search large"><span>⌕</span><input placeholder="ابحث بالاسم أو القسم..." value="${esc(state.q||'')}" oninput="state.q=this.value;render()"></div><div class="chips"><button class="chip ${!state.cat?'active':''}" onclick="state.cat='';render()">الكل</button>${cats.map(c=>`<button class="chip ${state.cat===c?'active':''}" onclick="state.cat='${esc(c)}';render()">${esc(c)}</button>`).join('')}</div></div><div class="product-grid">${arr.map(p=>`<button class="product" data-search="${esc((String(p.name)+" "+String(p.cat||"")).toLowerCase())}" onclick="add('${p.id}')"><div class="pic">${p.image?`<img src="${p.image}" alt="">`:`<span>${p.emoji||'📦'}</span>`}</div><span class="stock ${p.stock<=p.min&&p.type!=='service'?'danger':''}">${p.type==='service'?'خدمة':'متاح '+p.stock}</span><div class="pi"><b>${esc(p.name)}</b><small>${esc(p.cat||'بدون قسم')}</small><strong>${money(p.price)}</strong></div></button>`).join('')||`<div class="empty-state"><div class="empty-icon">📦</div><h2>لسه مفيش منتجات</h2><p>أضف منتجاتك من المخزون، وهتظهر هنا تلقائيًا في شاشة الكاشير.</p><button class="btn primary" onclick="state.page='inventory';render()">إضافة أول منتج</button></div>`}</div></section>
<section class="card cart pos-cart"><div class="cart-head"><div><span class="eyebrow">CURRENT ORDER</span><h2>السلة</h2></div><span class="cart-count">${state.cart.reduce((a,x)=>a+x.qty,0)} صنف</span></div>
<div class="form compact"><label>العميل<select id="saleCustomer" onchange="state.saleCustomer=this.value"><option value="">عميل نقدي / بدون تسجيل</option>${cs.map(c=>`<option value="${c.id}" ${state.saleCustomer===c.id?'selected':''}>${esc(c.name)}${c.phone?' • '+esc(c.phone):''}</option>`).join('')}</select></label><label>الحساب<select id="saleAccount" onchange="state.saleAccount=this.value">${accountOptions(state.saleAccount)}</select></label></div>
<div class="cart-items">${cartHTML()}</div><div class="note"><label>ملاحظة الفاتورة<textarea id="cartNote" oninput="state.cartNote=this.value" placeholder="ملاحظة للفاتورة أو التسليم...">${esc(state.cartNote)}</textarea></label></div>
<div class="total"><div class="sum"><span>الإجمالي</span><b>${money(sub())}</b></div><div class="sum"><span>الخصم</span><b class="discount-value">− ${money(state.discount)}</b></div><div class="sum grand"><span>المطلوب</span><span>${money(grand())}</span></div></div><div class="actions sale-actions"><button class="btn orange" onclick="discount()">خصم</button><button class="btn" onclick="clearCart()">تفريغ السلة</button><button class="btn primary" onclick="saveSale()">حفظ الفاتورة</button></div></section></div>`}
function cartHTML(){if(!state.cart.length)return'<div class="empty">ابدأ باختيار منتج من اليمين</div>';return state.cart.map((x,i)=>`<div class="cart-row"><div><b>${x.name}</b><br><small>${money(x.price)} × ${x.qty}</small></div><div class="qty"><button onclick="changeQty(${i},-1)">−</button>${x.qty}<button onclick="changeQty(${i},1)">+</button></div><b>${money(x.price*x.qty)}</b></div>`).join('')}
function sub(){return state.cart.reduce((a,x)=>a+x.price*x.qty,0)}function grand(){return Math.max(0,sub()-state.discount)}
async function add(id){let p=(await req('products')).find(x=>x.id===id);if(!p||p.active===false)return;if(p.type!=='service'){let x=state.cart.find(x=>x.id===id);let next=(x?.qty||0)+1;if(next>Number(p.stock||0))return toast('الكمية المطلوبة أكبر من المخزون');if(x)x.qty=next;else state.cart.push({id:p.id,name:p.name,price:Number(p.price)||0,cost:Number(p.cost)||0,qty:1,type:'product'});}else{let x=state.cart.find(x=>x.id===id);if(x)x.qty++;else state.cart.push({id:p.id,name:p.name,price:Number(p.price)||0,cost:Number(p.cost)||0,qty:1,type:'service'});}render()}
function changeQty(i,d){state.cart[i].qty+=d;if(state.cart[i].qty<1)state.cart.splice(i,1);render()}function clearCart(){state.cart=[];state.discount=0;state.cartNote='';render()}
function discount(){modal('تحديد الخصم',`<div class="actions">${[5,10,15,20].map(p=>`<button class="btn orange" onclick="applyDiscount(${p})">${p}%</button>`).join('')}</div><div class="form" style="margin-top:12px"><label>خصم بمبلغ<input id="dc" type="number"></label></div><button class="btn primary" style="margin-top:10px" onclick="state.discount=Math.min(sub(),Number(val('dc'))||0);closeModal();render()">تطبيق</button>`)}
function applyDiscount(p){state.discount=Math.round(sub()*p/100);closeModal();render()}
async function saveSale(){if(!(await requireOpenDay()))return;
  if(!state.cart.length)return toast('السلة فاضية');
  try{
    const [products,customers,repairs]=await Promise.all([req('products'),req('customers'),req('repairs')]);
    const customer=customers.find(c=>c.id===state.saleCustomer);
    const total=grand(), invoiceNo='INV-'+new Date().getFullYear()+'-'+String((await req('invoices')).length+1).padStart(5,'0');
    for(const i of state.cart){
      if(i.repairId)continue;
      const p=products.find(p=>p.id===i.id);
      if(!p)throw new Error('المنتج غير موجود');
      if(p.type!=='service' && Number(i.qty)>Number(p.stock||0))throw new Error('المخزون غير كافٍ للصنف: '+p.name);
    }
    const x={id:uid(),invoiceNo,date:now(),items:state.cart.map(i=>({...i})),subtotal:sub(),discount:state.discount,total,note:state.cartNote,account:state.saleAccount,customerId:customer?.id||'',customerName:customer?.name||'',customerPhone:customer?.phone||''};
    const inv={id:uid(),date:x.date,type:'بيع',total:x.total,ref:x.id,invoiceNo,note:x.note,account:x.account,customerId:x.customerId,customerName:x.customerName};
    const cashRow={id:uid(),date:x.date,type:'in',amount:x.total,account:x.account,reason:'بيع',ref:x.id,note:x.note};
    // Use one IndexedDB transaction for the whole sale.
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(['sales','invoices','cash','products','repairs','stockMoves'],'readwrite');
      tx.objectStore('sales').put(x); tx.objectStore('invoices').put(inv); tx.objectStore('cash').put(cashRow);
      for(const i of x.items){
        if(i.repairId){const rr=repairs.find(z=>z.id===i.repairId);if(rr){rr.status='تم التسليم';rr.deliveredAt=x.date;rr.paymentRecorded=true;rr.paymentInvoiceId=x.id;tx.objectStore('repairs').put(rr);}}
        else {const p=products.find(p=>p.id===i.id);if(p&&p.type!=='service'){p.stock=Math.max(0,p.stock-i.qty);tx.objectStore('products').put(p);tx.objectStore('stockMoves').put({id:uid(),date:x.date,productId:p.id,product:p.name,qty:-i.qty,before:Number(p.stock)+i.qty,after:Number(p.stock),reason:'بيع',ref:x.id});}}
      }
      tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('فشل حفظ الفاتورة'));tx.onabort=()=>reject(tx.error||new Error('تم إلغاء حفظ الفاتورة'));
    });
    await log('بيع',x); state.lastInvoice=x; clearCart(); state.saleAccount='drawer'; state.saleCustomer=''; toast('تم حفظ الفاتورة بنجاح');
    // Printing is optional; never block the sale with a print popup.
    render();
  }catch(e){console.error(e);toast(e.message||'حدث خطأ أثناء حفظ الفاتورة، ولم يتم تغيير السلة');}
}
async function repair(v){let rs=await req('repairs');let groups={new:rs.filter(r=>r.status==='تحت الفحص'),wait:rs.filter(r=>r.status==='بانتظار العميل'||r.status==='بانتظار التحصيل'),fixed:rs.filter(r=>r.status==='تم الإصلاح'),rejected:rs.filter(r=>r.status==='رفض'),done:rs.filter(r=>r.status==='تم التسليم')};const col=(title,a,action='')=>`<div class="stage"><h3>${title} (${a.length})</h3>${a.map(r=>`<div class="job"><b>${r.customer} • ${r.device}</b><small>${r.fault}</small><small>${r.phone||'بدون هاتف'}</small><small class="repair-date">📅 الاستلام: ${new Date(r.date).toLocaleDateString('ar-EG')} — ${new Date(r.date).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><div class="age">منذ ${Math.floor((Date.now()-new Date(r.date))/86400000)} يوم</div>${r.status!=='تم التسليم'?`<button class="btn mint" style="margin-top:8px" onclick="repairAction('${r.id}')">فتح الملف</button>`:''}</div>`).join('')||'<div class="empty">فارغ</div>'}</div>`;v.innerHTML=`<div class="section"><h2>لوحة الصيانة — بدون دفاتر</h2><button class="btn primary" onclick="newRepair()">＋ استلام جهاز</button></div><div class="pipeline repair-pipeline">${col('استلام / فحص',groups.new)}${col('بانتظار العميل',groups.wait)}${col('تم الإصلاح',groups.fixed)}${col('رفض',groups.rejected)}${col('تم التسليم',groups.done)}</div>`}
async function newRepair(){let cfg=(await req('settings')).find(x=>x.id==='repairTypes')||{types:[]};let types=cfg.types?.length?cfg.types:[{name:'فحص وصيانة عامة',price:0},{name:'HDMI',price:0},{name:'تنظيف',price:0},{name:'سوفتوير',price:0}];modal('استلام جهاز',`<div class="form"><label>اسم العميل<input id="rc"></label><label>الهاتف<input id="rp"></label><label>نوع الجهاز<select id="rd"><option>PS5</option><option>PS4</option><option>PS4 Pro</option><option>PS3</option><option>Xbox</option><option>دراع</option><option>يد تحكم أخرى</option><option>نينتندو سويتش</option><option>أخرى</option></select></label><label>نوع الصيانة<select id="rt">${types.map((t,i)=>`<option value="${i}">${esc(t.name)}${Number(t.price)>0?' — '+money(t.price):''}</option>`).join('')}</select></label><label>السعر<input id="ra" type="number" value="${types[0].price||0}"></label><label>العطل<input id="rf" placeholder="HDMI / Power / بوردة..."></label><label class="full">ملاحظات الاستلام<textarea id="rn" placeholder="ملحقات الجهاز، حالته، أي شيء مهم..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveRepair()">حفظ الاستلام</button>`);let rt=$('rt');if(rt)rt.onchange=()=>{let t=types[Number(rt.value)]||{};$('ra').value=t.price||0;};}
async function saveRepair(){if(!(await requireOpenDay()))return;let all=await req('repairs');let code='REP-'+new Date().getFullYear()+'-'+String(all.length+1).padStart(4,'0');let x={id:uid(),code,date:now(),customer:val('rc'),phone:val('rp'),device:val('rd'),fault:val('rf'),note:val('rn'),repairType:val('rt'),amount:Number(val('ra'))||0,status:'تحت الفحص',decision:'',account:'drawer'};if(!x.customer||!x.fault)return toast('الاسم والعطل مطلوبان');await put('repairs',x);await log('استلام صيانة',x);closeModal();toast('تم استلام الجهاز');render()}
async function repairAction(id){let r=(await req('repairs')).find(x=>x.id===id);if(!r)return;modal('ملف الصيانة',`<div class="repair-modal-head"><div class="repair-id">${esc(r.code||'REP-'+r.id.slice(0,6).toUpperCase())}</div><div><b>${esc(r.customer)}</b><p>${esc(r.device)} • ${esc(r.fault)}</p><small>استلام: ${new Date(r.date).toLocaleString('ar-EG')}</small></div></div><div class="grid two"><div class="card"><div class="kpi"><span>الهاتف</span><b>${esc(r.phone||'—')}</b></div><div class="kpi"><span>الحالة الحالية</span><b>${esc(r.status)}</b></div><div class="kpi"><span>قرار العميل</span><b>${esc(r.decision||'لم يحدد')}</b></div><div class="kpi"><span>الملاحظات</span><b>${esc(r.note||'—')}</b></div></div><div class="form"><label>الحالة<select id="rst"><option ${r.status==='تحت الفحص'?'selected':''}>تحت الفحص</option><option ${r.status==='بانتظار العميل'?'selected':''}>بانتظار العميل</option><option ${r.status==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.status==='رفض'?'selected':''}>رفض</option><option ${r.status==='تم التسليم'?'selected':''}>تم التسليم</option></select></label><label>قرار العميل<select id="rdec"><option value="" ${!r.decision?'selected':''}>لم يحدد</option><option ${r.decision==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.decision==='رفض'?'selected':''}>رفض</option></select></label><label>قيمة الصيانة<input id="ra" type="number" value="${r.amount||''}"></label><label>حساب التحصيل<select id="repairAccount">${accountOptions(r.account||'drawer')}</select></label><label class="full">ملاحظات<textarea id="rn2">${esc(r.note||'')}</textarea></label></div></div><div class="actions modal-actions">${r.phone?`<button class="btn whatsapp" onclick="whatsapp('${esc(r.phone)}','مرحباً ${esc(r.customer)}، معاك MAGHRABY STORE بخصوص جهاز ${esc(r.device)}. حالة الصيانة الحالية: ${esc(r.status)}.');">WhatsApp للعميل</button>`:''}<button class="btn primary" onclick="updateRepair('${id}')">حفظ وتحديث</button></div>`)}
async function updateRepair(id){let r=(await req('repairs')).find(x=>x.id===id),old=r.status,newStatus=val('rst');r.decision=val('rdec');r.amount=Number(val('ra'))||0;r.account=val('repairAccount')||'drawer';r.note=val('rn2');if(newStatus==='تم التسليم'&&old!=='تم التسليم'&&r.amount>0&&!r.paymentRecorded){r.status='بانتظار التحصيل';await put('repairs',r);closeModal();if(!state.cart.some(i=>i.repairId===r.id)){state.cart.push({id:'repair:'+r.id,name:'صيانة '+r.device+' — '+r.code,price:r.amount,cost:r.cost||0,qty:1,type:'service',repairId:r.id});}state.saleAccount=r.account||'drawer';state.saleCustomer='';state.page='sale';toast('تم تحويل الصيانة إلى الكاشير للتحصيل');render();return}r.status=newStatus;if(newStatus==='تم التسليم')r.deliveredAt=now();await put('repairs',r);await log('تحديث صيانة',r);closeModal();toast('تم تحديث الصيانة');render()}

async function inventory(v){let ps=await req('products'),sales=await req('sales'),purchasesX=await req('purchases'),returnsX=await req('returns');v.innerHTML=`<div class="section"><h2>المخزون — الكمية والقيمة والحد الأدنى</h2><button class="btn primary" onclick="productNew()">＋ منتج / خدمة</button></div><div class="grid stats">${stat('قيمة المخزون',ps.filter(p=>p.type!=='service').reduce((a,p)=>a+p.cost*p.stock,0),'بسعر التكلفة')}${stat('عدد الأصناف',ps.length,'منتجات + خدمات')}${stat('تحت الحد الأدنى',ps.filter(p=>p.type!=='service'&&p.stock<=p.min&&p.min>0).length,'جاهز للشراء')}</div><div class="card table-wrap"><table class="table"><thead><tr><th>صورة</th><th>المنتج</th><th>القسم</th><th>التكلفة</th><th>البيع</th><th>هامش الوحدة</th><th>الموجود</th><th>حد أدنى</th><th>إجراءات</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${p.image?`<img src="${p.image}" style="width:45px;height:35px;object-fit:cover;border-radius:7px">`:p.emoji}</td><td><b>${esc(p.name)}</b><br><small>${esc(p.note||'')}</small></td><td>${esc(p.cat)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${money(p.price-p.cost)}</td><td><span class="badge ${p.stock<=p.min?'redbg':'green'}">${p.type==='service'?'خدمة':p.stock}</span></td><td>${p.min}</td><td><div class="actions"><button class="btn orange" onclick="productEdit('${p.id}')">تعديل</button><button class="btn red" onclick="productDelete('${p.id}')">حذف</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">لا توجد منتجات</td></tr>'}</tbody></table></div>`}
async function productEdit(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;modal('تعديل المنتج',`<div class="form"><label>النوع<select id="pt"><option value="product" ${p.type==='product'?'selected':''}>منتج له مخزون</option><option value="service" ${p.type==='service'?'selected':''}>خدمة بدون مخزون</option></select></label><label>اسم المنتج<input id="pn" value="${esc(p.name)}"></label><label>القسم<input id="pc" value="${esc(p.cat||'')}"></label><label>سعر البيع<input id="pp" type="number" value="${p.price||0}"></label><label>التكلفة علينا<input id="pk" type="number" value="${p.cost||0}"></label><label>الكمية<input id="pq" type="number" value="${p.type==='service'?0:p.stock||0}"></label><label>الحد الأدنى<input id="pm" type="number" value="${p.min||0}"></label><label>إيموجي<input id="pe" value="${esc(p.emoji||'📦')}"></label><label class="full">ملاحظة<textarea id="pno">${esc(p.note||'')}</textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveProductEdit('${id}')">حفظ التعديل</button>`)}
async function saveProductEdit(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;let oldStock=Number(p.stock||0),type=val('pt')||'product';p.type=type;p.name=val('pn');p.cat=val('pc')||'أخرى';p.price=Number(val('pp'))||0;p.cost=Number(val('pk'))||0;if(type==='service'){p.stock=999999;p.min=0}else{p.stock=Math.max(0,Number(val('pq'))||0);p.min=Math.max(0,Number(val('pm'))||0)}p.emoji=val('pe')||'📦';p.note=val('pno');if(!p.name)return toast('اكتب اسم المنتج');await put('products',p);if(type!=='service'&&p.stock!==oldStock)await put('stockMoves',{id:uid(),date:now(),productId:p.id,product:p.name,qty:p.stock-oldStock,before:oldStock,after:p.stock,reason:'تعديل يدوي',ref:id});await log('تعديل منتج',p);closeModal();toast('تم تعديل المنتج');render()}
async function productDelete(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;let [ss,pu,re]=await Promise.all([req('sales'),req('purchases'),req('returns')]);let used=ss.some(x=>x.items?.some(i=>i.id===id))||pu.some(x=>x.productId===id)||re.some(x=>x.productId===id);if(used){return modal('لا يمكن الحذف النهائي',`<p>المنتج <b>${esc(p.name)}</b> مرتبط بتاريخ عمليات سابقة؛ الأفضل تعطيله حتى لا تتأثر الفواتير والتقارير.</p><button class="btn orange" onclick="closeModal();productDeactivate('${id}')">تعطيل المنتج</button>`)}if(confirm('حذف المنتج نهائيًا؟')){await db.transaction('products','readwrite').objectStore('products').delete(id);await log('حذف منتج',p);toast('تم حذف المنتج');render()}}
async function productDeactivate(id){let p=(await req('products')).find(x=>x.id===id);if(!p)return;p.active=false;await put('products',p);await log('تعطيل منتج',p);toast('تم تعطيل المنتج');render()}
function productNew(){modal('إضافة منتج / خدمة',`<div class="form"><label>النوع<select id="pt"><option value="product">منتج له مخزون</option><option value="service">خدمة بدون مخزون</option></select></label><label>اسم المنتج<input id="pn"></label><label>القسم<input id="pc" placeholder="أجهزة / دراعات / ألعاب / إكسسوارات / خدمات"></label><label>سعر البيع<input id="pp" type="number"></label><label>التكلفة علينا<input id="pk" type="number"></label><label>الكمية<input id="pq" type="number" value="1"></label><label>الحد الأدنى<input id="pm" type="number" value="1"></label><label>إيموجي<input id="pe" value="📦"></label><label>صورة<input id="pi" type="file" accept="image/*"></label><label class="full">ملاحظة<textarea id="pno"></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveProduct()">حفظ</button>`)}
function readFile(i){return new Promise(r=>{let f=$(i).files[0];if(!f)return r('');let x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(f)})}
async function saveProduct(){let type=val('pt')||'product';let p={id:uid(),type,name:val('pn'),cat:val('pc')||'أخرى',price:Number(val('pp'))||0,cost:Number(val('pk'))||0,stock:type==='service'?999999:Number(val('pq'))||0,min:type==='service'?0:Number(val('pm'))||0,emoji:val('pe')||'📦',image:await readFile('pi'),note:val('pno')};if(!p.name)return toast('اكتب اسم المنتج');await put('products',p);if(type!=='service')await put('stockMoves',{id:uid(),date:now(),productId:p.id,product:p.name,qty:p.stock,before:0,after:p.stock,reason:'إضافة منتج',ref:p.id});await log('إضافة منتج',p);closeModal();toast('تم حفظ المنتج');render()}
async function purchases(v){let ps=await req('products'),xs=await req('purchases');v.innerHTML=`<div class="section"><h2>المشتريات — البضاعة تدخل المخزون تلقائيًا</h2><button class="btn primary" onclick="purchaseNew()">＋ شراء بضاعة</button></div><div class="card"><div class="kpi"><span>قاعدة مهمة</span><b>ما سأبيعه للعميل = مشتريات / ما أستهلكه = مصروفات</b></div><div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الصنف</th><th>الكمية</th><th>التكلفة</th><th>الإجمالي</th><th>ملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.product}</td><td>${x.qty}</td><td>${money(x.unitCost)}</td><td>${money(x.total)}</td><td>${x.note||''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد مشتريات</td></tr>'}</tbody></table></div></div>`}
async function purchaseNew(){let ps=await req('products');modal('شراء بضاعة',`<div class="form"><label>الصنف<select id="bp">${ps.filter(p=>p.type!=='service').map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>الكمية<input id="bq" type="number" value="1"></label><label>تكلفة الوحدة<input id="bc" type="number"></label><label>حساب الدفع<select id="purchaseAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="bn" placeholder="مثال: شراء PS3 مستعمل من مورد..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="savePurchase()">حفظ</button>`)}
async function savePurchase(){if(!(await requireOpenDay()))return;let ps=await req('products'),p=ps.find(x=>x.id===val('bp'));if(!p)return toast('أضف منتجًا للمخزون أولًا');let q=Number(val('bq'))||1,c=Number(val('bc'))||p.cost,total=q*c;p.stock+=q;p.cost=c;await put('products',p);await put('stockMoves',{id:uid(),date:now(),productId:p.id,product:p.name,qty:q,before:p.stock-q,after:p.stock,reason:'شراء',ref:p.id});let x={id:uid(),date:now(),product:p.name,productId:p.id,qty:q,unitCost:c,total,note:val('bn')};await put('purchases',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:total,account:val('purchaseAccount')||'drawer',reason:'شراء بضاعة - '+p.name,ref:x.id,note:x.note});await log('شراء بضاعة',x);closeModal();toast('تمت الزيادة في المخزون وتسجيل الخرج');render()}
async function cash(v){let xs=await cashAll(),d=today(),balances=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));v.innerHTML=`<div class="grid three">${ACCOUNTS.map((a,i)=>`<div class="card"><div class="label">${a[1]}</div><div class="num">${money(balances[i].expected)}</div><div class="sub">بداية ${money(balances[i].opening)} · دخل ${money(balances[i].inc)} · خرج ${money(balances[i].out)}</div></div>`).join('')}</div><div class="section"><h2>دفتر الدخل والخرج</h2><div class="actions"><button class="btn mint" onclick="cashNew('in')">＋ دخل</button><button class="btn red" onclick="cashNew('out')">＋ خرج</button><button class="btn dark" onclick="transferNew()">⇄ تحويل بين الحسابات</button></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>الحساب</th><th>النوع</th><th>البيان</th><th>دخل</th><th>خرج</th><th>ملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${accountName(x.account)}</td><td>${x.type==='in'?'داخل':'خارج'}</td><td>${x.reason}</td><td>${x.type==='in'?money(x.amount):'—'}</td><td>${x.type==='out'?money(x.amount):'—'}</td><td>${x.note||''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد حركات</td></tr>'}</tbody></table></div>`}
function transferNew(){modal('تحويل بين الحسابات',`<div class="transfer-note">التحويل لا يعتبر دخلًا أو خرجًا للمحل؛ هو نقل رصيد من حساب إلى حساب فقط.</div><div class="form"><label>من حساب<select id="tf">${accountOptions('drawer')}</select></label><label>إلى حساب<select id="tt">${accountOptions('wallet')}</select></label><label>المبلغ<input id="ta" type="number"></label><label class="full">ملاحظة<textarea id="tn" placeholder="مثال: تحويل جزء من الدرج إلى المحفظة"></textarea></label></div><button class="btn dark" style="margin-top:11px" onclick="saveTransfer()">تنفيذ التحويل</button>`)}
async function saveTransfer(){if(!(await requireOpenDay()))return;let from=val('tf'),to=val('tt'),amount=Number(val('ta'))||0;if(from===to)return toast('اختار حسابين مختلفين');if(!amount)return toast('اكتب المبلغ');let x={id:uid(),date:now(),from,to,amount,note:val('tn')};await put('transfers',x);await put('cash',{id:uid(),date:x.date,type:'out',amount,account:from,reason:'تحويل إلى '+accountName(to),ref:x.id,note:x.note,transfer:true});await put('cash',{id:uid(),date:x.date,type:'in',amount,account:to,reason:'تحويل من '+accountName(from),ref:x.id,note:x.note,transfer:true});await log('تحويل بين الحسابات',x);closeModal();toast('تم التحويل بدون التأثير على صافي دخل/خرج المحل');render()}
function cashNew(type){let opts=type==='in'?['دخل آخر','تحصيل','عربون','استرداد من مورد','أخرى']:['سلفة موظف','إيجار','كهرباء','مياه','معطر واستهلاك','نقل','أخرى'];modal(type==='in'?'دخل جديد':'خرج جديد',`<div class="form"><label>الحساب<select id="cashAccount">${accountOptions('drawer')}</select></label><label>المبلغ<input id="ca" type="number"></label><label>البيان<select id="cr">${opts.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="full">ملاحظة<textarea id="cn"></textarea></label></div><button class="btn ${type==='in'?'mint':'red'}" style="margin-top:11px" onclick="saveCash('${type}')">حفظ</button>`)}
async function saveCash(type){let a=Number(val('ca'))||0;if(!a)return toast('اكتب المبلغ');let x={id:uid(),date:now(),type,amount:a,account:val('cashAccount')||'drawer',reason:val('cr'),note:val('cn')};await put('cash',x);await log('حركة خزنة',x);closeModal();toast('تم حفظ الحركة');render()}
async function expenses(v){let xs=await req('expenses');let total=xs.reduce((a,x)=>a+x.amount,0),todayTotal=xs.filter(x=>x.date.slice(0,10)===today()).reduce((a,x)=>a+x.amount,0);v.innerHTML=`<div class="page-head"><div><span class="eyebrow">EXPENSES</span><h2>مصروفات المحل</h2><p>سجل كل خرج تشغيلي بشكل واضح، مع الحساب الذي تم الدفع منه.</p></div><button class="btn red" onclick="expenseNew()">＋ إضافة مصروف</button></div><div class="grid three"><div class="card kpi-card"><span>مصروفات اليوم</span><b>${money(todayTotal)}</b></div><div class="card kpi-card"><span>إجمالي المصروفات</span><b>${money(total)}</b></div><div class="card kpi-card"><span>عدد العمليات</span><b>${xs.length} مصروف</b></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>التاريخ والوقت</th><th>نوع المصروف</th><th>حساب الدفع</th><th>المبلغ</th><th>ملاحظة</th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td><b>${esc(x.type)}</b></td><td>${accountName(x.account||'drawer')}</td><td class="negative">${money(x.amount)}</td><td>${esc(x.note||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد مصروفات مسجلة حتى الآن</td></tr>'}</tbody></table></div>`}
function expenseNew(){modal('مصروف تشغيل',`<div class="form"><label>النوع<select id="et"><option>إيجار</option><option>كهرباء</option><option>مياه</option><option>إنترنت</option><option>معطر / تنظيف</option><option>نقل</option><option>أخرى</option></select></label><label>المبلغ<input id="ea" type="number"></label><label>حساب الدفع<select id="expenseAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="en"></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveExpense()">حفظ</button>`)}
async function saveExpense(){if(!(await requireOpenDay()))return;let a=Number(val('ea'))||0,x={id:uid(),date:now(),type:val('et'),amount:a,note:val('en')};await put('expenses',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:a,account:val('expenseAccount')||'drawer',reason:x.type,ref:x.id,note:x.note});await log('مصروف',x);closeModal();toast('تم تسجيل المصروف');render()}
async function staff(v){let xs=await req('staff'),cashx=await req('cash');v.innerHTML=`<div class="section"><h2>الفنيون والموظفون — السلف والمستحقات</h2><button class="btn primary" onclick="staffNew()">＋ موظف / فني</button></div><div class="card"><p style="color:var(--muted)">هنا نسجل الأشخاص العاملين وسلفهم. السلفة تظهر تلقائيًا كخرج من الخزنة، بدل ما تختلط بالمشتريات أو مصروفات المحل.</p><div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>الدور</th><th>السلف</th><th>ملاحظات</th><th></th></tr></thead><tbody>${xs.map(x=>{let adv=cashx.filter(c=>c.type==='out'&&c.reason==='سلفة موظف'&&c.staffId===x.id).reduce((a,c)=>a+c.amount,0);return `<tr><td><b>${x.name}</b></td><td>${x.role}</td><td>${money(adv)}</td><td>${x.note||''}</td><td><button class="btn orange" onclick="advance('${x.id}')">سلفة</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">أضف الفنيين والموظفين عند الحاجة</td></tr>'}</tbody></table></div></div>`}
function staffNew(){modal('إضافة فني / موظف',`<div class="form"><label>الاسم<input id="sn"></label><label>الدور<input id="sr" placeholder="فني / موظف / إداري"></label><label class="full">ملاحظة<textarea id="sno"></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveStaff()">حفظ</button>`)}
async function saveStaff(){let x={id:uid(),name:val('sn'),role:val('sr'),note:val('sno')};await put('staff',x);closeModal();toast('تم إضافة الشخص');render()}
async function advance(id){let s=(await req('staff')).find(x=>x.id===id);modal('سلفة — '+s.name,`<div class="form"><label>المبلغ<input id="ava" type="number"></label><label>حساب الدفع<select id="advanceAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظة<textarea id="avn"></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveAdvance('${id}')">تسجيل السلفة</button>`)}
async function saveAdvance(id){let a=Number(val('ava'))||0;if(!a)return toast('اكتب المبلغ');await put('cash',{id:uid(),date:now(),type:'out',amount:a,account:val('advanceAccount')||'drawer',reason:'سلفة موظف',staffId:id,note:val('avn')});closeModal();toast('تم تسجيل السلفة كخرج من الخزنة');render()}
async function customers(v){let xs=await req('customers');let q=(state.q||'').toLowerCase();xs=xs.filter(x=>x.name.toLowerCase().includes(q)||String(x.phone||'').includes(q));v.innerHTML=`<div class="section"><h2>العملاء والخصومات الذكية</h2><button class="btn primary" onclick="customerNew()">＋ عميل</button></div><div class="card"><p style="color:var(--muted)">احفظ العميل الدائم وملاحظته، ثم استخدم قرار الخصم في كل فاتورة بدل خصم عشوائي.</p><div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>الهاتف</th><th>ملاحظات</th><th>تاريخ الإضافة</th></tr></thead><tbody>${xs.map(x=>`<tr><td><b>${x.name}</b></td><td>${x.phone||''}</td><td>${x.note||''}</td><td>${new Date(x.date).toLocaleDateString('ar-EG')}</td></tr>`).join('')}</tbody></table></div></div>`}
function customerNew(){modal('عميل جديد',`<div class="form"><label>الاسم<input id="cname"></label><label>الهاتف<input id="cphone"></label><label class="full">ملاحظة<textarea id="cnote" placeholder="دائم / يفضل خصم / ملاحظة خدمة..."></textarea></label></div><button class="btn primary" style="margin-top:11px" onclick="saveCustomer()">حفظ</button>`)}
async function saveCustomer(){let x={id:uid(),date:now(),name:val('cname'),phone:val('cphone'),note:val('cnote')};if(!x.name)return toast('اكتب اسم العميل');await put('customers',x);closeModal();toast('تم حفظ العميل');render()}
async function returns(v){let rs=await req('returns');let sales=await req('sales');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">RETURNS</span><h2>المرتجعات</h2><p>إرجاع الصنف للمخزون ورد المبلغ من الحساب الصحيح بدون كسر حركة اليوم.</p></div><button class="btn primary" onclick="returnNew()">＋ تسجيل مرتجع</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الفاتورة</th><th>الصنف</th><th>الكمية</th><th>المبلغ</th><th>الحساب</th><th>السبب</th></tr></thead><tbody>${rs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.invoiceRef||'—'}</td><td>${esc(x.itemName)}</td><td>${x.qty}</td><td>${money(x.total)}</td><td>${accountName(x.account)}</td><td>${esc(x.reason||'')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد مرتجعات</td></tr>'}</tbody></table></div>`}
async function returnNew(){let sales=await req('sales');if(!sales.length)return toast('لا توجد فواتير بيع يمكن إرجاعها');modal('تسجيل مرتجع',`<div class="form"><label class="full">الفاتورة<select id="rrsale">${sales.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<option value="${x.id}">${new Date(x.date).toLocaleString('ar-EG')} • ${esc(x.customerName||'عميل نقدي')} • ${money(x.total)}</option>`).join('')}</select></label><label>الصنف<select id="rritem"></select></label><label>الكمية<input id="rrqty" type="number" value="1" min="1"></label><label>حساب رد المبلغ<select id="rraccount">${accountOptions('drawer')}</select></label><label class="full">سبب المرتجع<textarea id="rrreason" placeholder="عيب / تغيير رأي / غير مناسب... "></textarea></label></div><button class="btn red" style="margin-top:11px" onclick="saveReturn()">تسجيل المرتجع ورد المبلغ</button>`);let sel=$('rrsale');let fill=async()=>{let s=(await req('sales')).find(x=>x.id===sel.value);$('rritem').innerHTML=(s?.items||[]).map((i,n)=>`<option value="${n}">${esc(i.name)} • ${i.qty} × ${money(i.price)}</option>`).join('')};sel.onchange=fill;await fill()}
async function saveReturn(){if(!(await requireOpenDay()))return;let sales=await req('sales'),s=sales.find(x=>x.id===val('rrsale'));if(!s)return;let idx=Number(val('rritem')),item=s.items[idx],qty=Number(val('rrqty'))||0;if(!item||qty<1||qty>item.qty)return toast('كمية المرتجع غير صحيحة');let total=qty*Number(item.price||0),x={id:uid(),date:now(),saleId:s.id,invoiceRef:s.id.slice(0,8),itemName:item.name,itemId:item.id,qty,total,account:val('rraccount')||'drawer',reason:val('rrreason')};await put('returns',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:total,account:x.account,reason:'مرتجع بيع - '+item.name,ref:x.id});await put('invoices',{id:uid(),date:x.date,type:'مرتجع',total,ref:x.id,account:x.account,note:x.reason});let ps=await req('products'),p=ps.find(p=>p.id===item.id);if(p&&p.type!=='service'){p.stock+=qty;await put('products',p)}await log('مرتجع بيع',x);closeModal();toast('تم تسجيل المرتجع وإعادة الكمية للمخزون');render()}
async function needs(v){let ps=await req('products'),low=ps.filter(p=>p.type!=='service'&&p.stock<=p.min&&p.min>0);v.innerHTML=`<div class="section"><h2>قائمة الاحتياجات — النظام يرشحها لك</h2><button class="btn primary" onclick="state.page='purchases';render()">فتح المشتريات</button></div><div class="card">${low.map(p=>`<div class="kpi"><span>📦 <b>${p.name}</b><small> — الموجود ${p.stock} / الحد ${p.min}</small></span><button class="btn orange" onclick="toast('تم تمييز ${p.name} كاحتياج')">مطلوب</button></div>`).join('')||'<div class="empty">مفيش أصناف تحت الحد الأدنى 🎉</div>'}</div>`}
async function reports(v){let [s,r,e,c,days]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('days')]),d=today(),dt=new Date(),weekStart=new Date(dt);weekStart.setDate(dt.getDate()-6);weekStart.setHours(0,0,0,0),monthStart=new Date(dt.getFullYear(),dt.getMonth(),1),yearStart=new Date(dt.getFullYear(),0,1);const period=(start)=>({start,rows:c.filter(x=>new Date(x.date)>=start&&new Date(x.date)<=dt)}),sumRows=rows=>({inc:rows.filter(x=>x.type==='in'&&!x.transfer).reduce((a,x)=>a+x.amount,0),out:rows.filter(x=>x.type==='out'&&!x.transfer).reduce((a,x)=>a+x.amount,0)}),W=period(weekStart),M=period(monthStart),Y=period(yearStart),sd=s.filter(x=>x.date.slice(0,10)===d),rd=r.filter(x=>x.date.slice(0,10)===d&&x.status==='تم التسليم'),ed=e.filter(x=>x.date.slice(0,10)===d),sales=sd.reduce((a,x)=>a+x.total,0),cogs=sd.reduce((a,x)=>a+x.items.reduce((z,i)=>z+i.cost*i.qty,0),0),repIncome=rd.reduce((a,x)=>a+(x.amount||0),0),op=ed.reduce((a,x)=>a+x.amount,0),profit=sales+repIncome-cogs-op,closed=days.find(x=>x.date===d);let B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));v.innerHTML=`<div class="grid stats">${stat('مبيعات اليوم',sales,'بعد الخصم')}${stat('دخل الصيانة',repIncome,'المسلّم اليوم')}${stat('مصروفات التشغيل',op,'بدون المشتريات')}${stat('الربح التقريبي',profit,'بعد التكلفة والمصروفات')}${stat('المتوقع في الدرج',B[0].expected,'رصيد بداية + حركة اليوم')}${stat('إجمالي الأرصدة الرقمية',B[1].expected+B[2].expected,'محفظة + InstaPay')}</div><div class="section"><h2>🔒 إقفال اليوم</h2><button class="btn primary" onclick="closeDay()">عدّ الدرج والمحافظ وإقفال اليوم</button></div><div class="card close-box"><div class="grid three">${ACCOUNTS.map((a,i)=>`<div><small>${a[1]}</small><div class="expected">${money(B[i].expected)}</div><div class="sub">بداية ${money(B[i].opening)} · دخل ${money(B[i].inc)} · خرج ${money(B[i].out)}</div></div>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><b>${closed?'اليوم مقفول بالفعل ويمكن مراجعة أرقامه.':'الإقفال يحفظ الرصيد الفعلي لكل حساب ليصبح رصيد بداية اليوم التالي تلقائيًا.'}</b></div><div class="section"><h2>📊 الدخل والخرج — أسبوعي / شهري / سنوي</h2><button class="btn dark" onclick="window.print()">طباعة / حفظ PDF</button></div><div class="grid three">${[['الأسبوع الحالي',W],['الشهر الحالي',M],['السنة الحالية',Y]].map(([n,x])=>{let q=sumRows(x.rows);return `<div class="card"><h3>${n}</h3><div class="kpi"><span>إجمالي الداخل</span><b class="positive">${money(q.inc)}</b></div><div class="kpi"><span>إجمالي الخارج</span><b class="negative">${money(q.out)}</b></div><div class="kpi"><span>صافي الحركة</span><b>${money(q.inc-q.out)}</b></div></div>`}).join('')}</div><div class="section"><h2>تفصيل حسب الحساب</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>الفترة</th>${ACCOUNTS.map(a=>`<th>${a[1]} دخل</th><th>${a[1]} خرج</th>`).join('')}</tr></thead><tbody>${[['أسبوعي',W.rows],['شهري',M.rows],['سنوي',Y.rows]].map(([n,rows])=>`<tr><td>${n}</td>${ACCOUNTS.map(a=>{let z=sumRows(rows.filter(x=>x.account===a[0]));return `<td>${money(z.inc)}</td><td>${money(z.out)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="section"><h2>تحليل اليوم</h2></div><div class="grid two"><div class="card"><div class="kpi"><span>عدد عمليات البيع</span><b>${sd.length}</b></div><div class="kpi"><span>خصومات اليوم</span><b>${money(sd.reduce((a,x)=>a+x.discount,0))}</b></div><div class="kpi"><span>أجهزة تم تسليمها</span><b>${rd.length}</b></div></div><div class="card"><div class="kpi"><span>قيمة المبيعات + الصيانة</span><b>${money(sales+repIncome)}</b></div><div class="kpi"><span>تكلفة البضاعة</span><b>${money(cogs)}</b></div><div class="kpi"><span>هامش تقريبي</span><b class="${profit>=0?'positive':'negative'}">${money(profit)}</b></div><div class="section"><h2>تفاصيل النشاط</h2></div><div class="grid four"><div class="kpi"><span>المشتريات اليوم</span><b>${money((await req('purchases')).filter(x=>x.date.slice(0,10)===d).reduce((a,x)=>a+x.total,0))}</b></div><div class="kpi"><span>المرتجعات اليوم</span><b>${money((await req('returns')).filter(x=>x.date.slice(0,10)===d).reduce((a,x)=>a+x.total,0))}</b></div><div class="kpi"><span>عدد المصروفات</span><b>${ed.length}</b></div><div class="kpi"><span>إجمالي الخصومات</span><b>${money(sd.reduce((a,x)=>a+x.discount,0))}</b></div></div><div class="section"><h2>🗂️ مراجعة التاريخ</h2><span class="muted">السجل لا يُحذف تلقائيًا حسب السنة؛ يمكنك مراجعة سنوات متعددة طالما بيانات المتصفح موجودة.</span></div><div class="card"><div class="form compact"><label>السنة<select id="historyYear"></select></label><label>الشهر<select id="historyMonth"><option value="all">كل الشهور</option><option value="01">يناير</option><option value="02">فبراير</option><option value="03">مارس</option><option value="04">أبريل</option><option value="05">مايو</option><option value="06">يونيو</option><option value="07">يوليو</option><option value="08">أغسطس</option><option value="09">سبتمبر</option><option value="10">أكتوبر</option><option value="11">نوفمبر</option><option value="12">ديسمبر</option></select></label></div><div id="historyResult" style="margin-top:14px"></div></div><div class="section"><h2>💾 حفظ طويل المدى</h2></div><div class="card"><p class="muted">البرنامج لا يضع حدًا مثل سنة أو سنتين؛ المعاملات تظل محفوظة محليًا حتى تحذف بيانات الموقع/المتصفح أو تستورد نسخة أخرى. اعمل Backup دوريًا، ويفضل نسخة شهرية وسنوية خارج الجهاز.</p></div></div>`;initHistory()}
async function initHistory(){let years=new Set([String(new Date().getFullYear())]);for(const store of ['cash','sales','repairs','expenses','purchases'])for(const x of await req(store)){if(x.date)years.add(String(new Date(x.date).getFullYear()))}let ys=[...years].sort((a,b)=>b.localeCompare(a));$('historyYear').innerHTML=ys.map(y=>`<option value="${y}">${y}</option>`).join('');$('historyYear').value=String(new Date().getFullYear());$('historyMonth').value='all';$('historyYear').onchange=historyRefresh;$('historyMonth').onchange=historyRefresh;historyRefresh()}
async function historyRefresh(){let y=$('historyYear').value,m=$('historyMonth').value,rows=(await cashAll()).filter(x=>{let d=new Date(x.date);return String(d.getFullYear())===y&&(m==='all'||String(d.getMonth()+1).padStart(2,'0')===m)}),inc=rows.filter(x=>x.type==='in'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0),out=rows.filter(x=>x.type==='out'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0);let by=Object.fromEntries(ACCOUNTS.map(a=>[a[0],{in:0,out:0}]));rows.forEach(x=>{if(by[x.account]&&!x.transfer)by[x.account][x.type]+=Number(x.amount||0)});$('historyResult').innerHTML=`<div class="grid four"><div class="kpi"><span>إجمالي الداخل</span><b class="positive">${money(inc)}</b></div><div class="kpi"><span>إجمالي الخارج</span><b class="negative">${money(out)}</b></div><div class="kpi"><span>صافي الحركة</span><b>${money(inc-out)}</b></div><div class="kpi"><span>عدد الحركات</span><b>${rows.length}</b></div></div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>الحساب</th><th>الدخل</th><th>الخرج</th><th>الصافي</th></tr></thead><tbody>${ACCOUNTS.map(a=>`<tr><td>${a[1]}</td><td>${money(by[a[0]].in)}</td><td>${money(by[a[0]].out)}</td><td>${money(by[a[0]].in-by[a[0]].out)}</td></tr>`).join('')}</tbody></table></div>`}

async function closeDay(){if(!(await currentDayOpen()))return toast('افتح اليوم أولًا قبل الإقفال');let d=today(),B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),old=await dayRecord(d);modal('إقفال اليوم — عدّ كل الحسابات',`<div class="grid three">${ACCOUNTS.map((a,i)=>`<div class="card"><small>${a[1]} — المتوقع</small><div class="expected">${money(B[i].expected)}</div><small>بداية ${money(B[i].opening)} + دخل ${money(B[i].inc)} − خرج ${money(B[i].out)}</small></div>`).join('')}</div><div class="form" style="margin-top:12px">${ACCOUNTS.map(a=>`<label>الرصيد الفعلي — ${a[1]}<input id="count_${a[0]}" type="number" value="${old?.[a[0]+'Counted']??(a[0]==='drawer'?(old?.counted??''):'')}"></label>`).join('')}<label class="full">ملاحظة الإقفال<textarea id="dn">${old?.note||''}</textarea></label></div><div id="difference" style="margin-top:10px"></div><button class="btn primary" style="margin-top:10px" onclick="saveDay('${d}')">حفظ الإقفال</button>`);for(const a of ACCOUNTS){$('count_'+a[0]).oninput=()=>{let html=ACCOUNTS.map(x=>{let expected=B.find((_,i)=>ACCOUNTS[i][0]===x[0]).expected,count=Number($('count_'+x[0]).value)||0;return `<div class=\"kpi\"><span>${x[1]}</span><b class=\"${count-expected===0?'positive':'negative'}\">${count-expected===0?'مطابق':'فرق '+money(count-expected)}</b></div>`}).join('');$('difference').innerHTML=html}}}
async function saveDay(d){let B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),x={id:d,date:d,note:val('dn'),closedAt:now()};ACCOUNTS.forEach((a,i)=>{let counted=Number(val('count_'+a[0]))||0;x[a[0]+'Opening']=B[i].opening;x[a[0]+'Expected']=B[i].expected;x[a[0]+'Counted']=counted;x[a[0]+'Difference']=counted-B[i].expected});x.expected=x.drawerExpected;x.counted=x.drawerCounted;x.difference=x.drawerDifference;await put('days',x);closeModal();toast('تم إقفال اليوم وحفظ أرصدة الدرج والمحفظة وInstaPay');render()}
async function invoices(v){let xs=await req('invoices');v.innerHTML=`<div class="section"><h2>الفواتير</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>النوع</th><th>الإجمالي</th><th>ملاحظة</th><th></th></tr></thead><tbody>${xs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.invoiceNo||x.ref?.slice(0,8)||'—')}</td><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.type}</td><td>${money(x.total)}</td><td>${x.note||''}</td><td>${x.type==='بيع'?`<button class="btn" onclick="reprint('${x.ref}')">طباعة</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لا توجد فواتير</td></tr>'}</tbody></table></div>`}
async function reprint(ref){let x=(await req('sales')).find(s=>s.id===ref);if(x)printInvoice(x)}
function printInvoice(x){let items=x.items.map(i=>`<tr><td>${i.name}</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.price*i.qty)}</td></tr>`).join('');let w=window.open('','_blank');if(!w)return toast('المتصفح منع نافذة الطباعة');w.document.write(`<html dir="rtl"><head><title>فاتورة MAGHRABY STORE</title><style>body{font-family:Arial;padding:25px;color:#102a43}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:right}.total{font-size:22px;font-weight:bold;margin-top:20px}.note{margin-top:15px;background:#f4f7f8;padding:10px}</style></head><body><div style="display:flex;align-items:center;gap:12px;border-bottom:2px solid #0b86ff;padding-bottom:12px"><img src="${new URL('public/logo.png',location.href).href}" style="width:64px;height:64px;object-fit:contain"><h1 style="margin:0">MAGHRABY STORE</h1></div><p>${new Date(x.date).toLocaleString('ar-EG')}</p><table><tr><th>الصنف</th><th>العدد</th><th>السعر</th><th>الإجمالي</th></tr>${items}</table><p>قبل الخصم: ${money(x.subtotal)}</p><p>الخصم: ${money(x.discount)}</p><div class="total">الإجمالي: ${money(x.total)}</div><div class="note">${x.note||''}</div><script>window.print()<\/script></body></html>`);w.document.close()}
async function settings(v){let fs=(await req('settings')).find(x=>x.id==='finance')||{};v.innerHTML=`<div class="page-head"><div><span class="eyebrow">CONTROL CENTER</span><h2>الإعدادات والنظام</h2><p>البيانات محلية على الجهاز، وتقدر تعمل نسخة احتياطية في أي وقت.</p></div></div><div class="grid two"><div class="card settings-card"><div class="card-title"><div><h3>💰 أرصدة البداية</h3><small>لو عندك مبلغ موجود قبل أول يوم استخدام، اكتبه هنا.</small></div></div><div class="form compact"><label>رصيد الدرج<input id="open_drawer" type="number" value="${fs.drawerOpening||''}"></label><label>رصيد المحفظة<input id="open_wallet" type="number" value="${fs.walletOpening||''}"></label><label>رصيد InstaPay<input id="open_instapay" type="number" value="${fs.instapayOpening||''}"></label></div><button class="btn primary" onclick="saveOpenings()">حفظ أرصدة البداية</button></div><div class="card settings-card"><div class="card-title"><div><h3>💾 النسخ الاحتياطي</h3><small>احتفظ بنسخة خارج الجهاز بشكل دوري.</small></div></div><div class="actions"><button class="btn primary" onclick="backup()">تصدير نسخة احتياطية</button><label class="btn">استيراد<input type="file" hidden accept=".json" onchange="restore(this.files[0])"></label></div></div><div class="card settings-card"><div class="card-title"><div><h3>🔧 أنواع وأسعار الصيانة</h3><small>أنواع جاهزة تظهر عند استلام الصيانة.</small></div></div><div id="repairTypesList">${((await req('settings')).find(x=>x.id==='repairTypes')?.types||[]).map(t=>`<div class="kpi"><span>${esc(t.name)}</span><b>${money(t.price)}</b></div>`).join('')||'<div class="empty">لم تضف أنواع صيانة بعد</div>'}</div><button class="btn primary" onclick="repairTypeAdd()">＋ إضافة نوع</button></div><div class="card settings-card"><div class="card-title"><div><h3>🎨 الهوية</h3><small>MAGHRABY STORE — ألوان مستوحاة من اللوجو الأصلي.</small></div></div><img src="public/logo.png" class="settings-logo"><p class="muted">اللوجو الرسمي محفوظ بصيغة PNG داخل المشروع، والواجهة مبنية حول الأزرق الكهربائي، السماوي، الأخضر، والكحلي الموجودين في الهوية.</p></div><div class="card settings-card"><div class="card-title"><div><h3>🧠 قواعد النظام</h3><small>المنطق الأساسي اللي بيحافظ على الحسابات.</small></div></div><ul class="rules"><li>البيع يسجل دخل في الحساب المختار ويقلل مخزون المنتجات.</li><li>المشتريات تسجل خرج وتزيد المخزون.</li><li>المصروفات والسلف تخرج من الحساب المختار.</li><li>التحويل بين الدرج والمحفظة وInstaPay لا يغير صافي دخل/خرج المحل.</li><li>إقفال اليوم يحفظ الرصيد الفعلي ليصبح رصيد بداية اليوم التالي.</li></ul></div></div>`}
async function repairTypeAdd(){let cfg=(await req('settings')).find(x=>x.id==='repairTypes')||{id:'repairTypes',types:[]};modal('إضافة نوع صيانة',`<div class="form"><label>الاسم<input id="rtn"></label><label>السعر<input id="rtp" type="number"></label></div><button class="btn primary" style="margin-top:10px" onclick="repairTypeSave()">حفظ</button>`)}
async function repairTypeSave(){let cfg=(await req('settings')).find(x=>x.id==='repairTypes')||{id:'repairTypes',types:[]};let name=val('rtn');if(!name)return toast('اكتب اسم نوع الصيانة');cfg.types=[...(cfg.types||[]),{id:uid(),name,price:Number(val('rtp'))||0}];await put('settings',cfg);closeModal();toast('تم حفظ نوع الصيانة');render()}
async function saveOpenings(){let x={id:'finance',drawerOpening:Number(val('open_drawer'))||0,walletOpening:Number(val('open_wallet'))||0,instapayOpening:Number(val('open_instapay'))||0};await put('settings',x);toast('تم حفظ أرصدة البداية');render()}

async function backup(){let data={version:10,exportedAt:now(),app:'MAGHRABY STORE FINAL',stores:{}};for(const s of stores)data.stores[s]=await req(s);data.stores.stockMoves=await req('stockMoves');let blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MAGHRABY_STORE_BACKUP_'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم إنشاء النسخة الاحتياطية وحفظها في التنزيلات')}
async function restore(file){if(!file)return;try{let d=JSON.parse(await file.text());if(!d.stores||typeof d.stores!=='object')throw new Error('invalid');if(!confirm('استرجاع النسخة سيستبدل كل البيانات الحالية بالنسخة المختارة. هل تريد المتابعة؟'))return;await new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');for(const s of stores){const os=tx.objectStore(s);os.clear();for(const x of (d.stores[s]||[]))os.put(x)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});toast('تم استرجاع النسخة بالكامل');render()}catch(e){console.error(e);toast('ملف النسخة غير صالح أو تعذر استرجاعه')}}
async function backupPage(v){let counts=[];for(const s of stores)counts.push([s,(await req(s)).length]);v.innerHTML=`<div class="page-head"><div><span class="eyebrow">DATA SAFETY</span><h2>النسخ الاحتياطي</h2><p>حافظ على تاريخ المحل بالكامل خارج الجهاز، ويمكنك استرجاعه عند الحاجة.</p></div></div><div class="grid two"><div class="card"><h3>💾 إنشاء نسخة احتياطية</h3><p class="muted">النسخة تشمل المبيعات، الفواتير، المخزون، الصيانة، المصروفات، المشتريات، العملاء، الخزنة، الإقفالات، التحويلات، المرتجعات وسجل الحركات.</p><button class="btn primary" onclick="backup()">⇩ إنشاء Backup الآن</button></div><div class="card"><h3>↩ استرجاع نسخة</h3><p class="muted">الاسترجاع يستبدل البيانات الحالية بالكامل. اعمل Backup قبل الاسترجاع إذا عندك بيانات مهمة.</p><label class="btn dark">اختيار ملف Backup<input type="file" hidden accept="application/json,.json" onchange="restore(this.files[0])"></label></div></div><div class="section"><h2>حالة البيانات الحالية</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>القسم</th><th>عدد السجلات</th></tr></thead><tbody>${counts.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td></tr>`).join('')}</tbody></table></div><div class="card"><b>ملاحظة:</b> لا يوجد حذف تلقائي للمعاملات بعد سنة. البيانات تظل موجودة طالما بيانات الموقع/المتصفح موجودة، والـBackup الخارجي هو الحماية الأساسية من الفورمات أو فقدان بيانات المتصفح.</div>`}
async function log(action,data){await put('audit',{id:uid(),date:now(),action,data})}
function modal(t,b){$('mt').textContent=t;$('mb').innerHTML=b;$('modal').classList.remove('hidden')}function closeModal(){$('modal').classList.add('hidden')}$('mc').onclick=closeModal;
function toast(t){let x=document.createElement('div');x.className='toast';x.textContent=t;$('toast').appendChild(x);setTimeout(()=>x.remove(),2300)}
boot();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});

