const DEFAULT_REPAIR_TYPES=[
  {id:'rt-general',name:'فحص وصيانة عامة',price:0},
  {id:'rt-hdmi',name:'HDMI',price:0},
  {id:'rt-clean',name:'تنظيف',price:0},
  {id:'rt-software',name:'سوفتوير',price:0},
  {id:'rt-games',name:'تنزيل ألعاب',price:0},
  {id:'rt-mod',name:'تعديل جهاز',price:0}
];
function repairTypesList(cfg){const got=Array.isArray(cfg?.types)?cfg.types:[];const names=new Set(got.map(x=>x.name));return [...got,...DEFAULT_REPAIR_TYPES.filter(x=>!names.has(x.name))]}

async function newRepair(){
  if(!(await requireOpenDay()))return;
  const cfg=(await req('settings')).find(x=>x.id==='repairTypes')||{};const types=repairTypesList(cfg);
  modal('استلام جهاز',`<div class="form">
  <label>اسم العميل<input id="rc"></label><label>الهاتف<input id="rp" inputmode="tel"></label>
  <label>نوع الجهاز<select id="rd"><option>PS5</option><option>PS4</option><option>PS4 Pro</option><option>PS3</option><option>Xbox</option><option>دراع</option><option>يد تحكم أخرى</option><option>نينتندو سويتش</option><option>أخرى</option></select></label>
  <label>Serial Number<input id="rserial" placeholder="Serial الجهاز / الدراع"></label>
  <label>نوع الصيانة<select id="rt">${types.map((t,i)=>`<option value="${i}">${esc(t.name)}${Number(t.price)>0?' — '+money(t.price):''}</option>`).join('')}</select></label>
  <label>السعر<input id="ra" type="number" value="${types[0]?.price||0}"></label>
  <label class="full">العطل<input id="rf" placeholder="HDMI / Power / بوردة / أزرار الدراع..."></label>
  <label class="full">ملاحظات الاستلام<textarea id="rn" placeholder="ملحقات الجهاز، حالته، أي شيء مهم..."></textarea></label>
  </div><button class="btn primary" style="margin-top:11px" onclick="saveRepair()">حفظ الاستلام</button>`);
  const rt=$('rt');if(rt)rt.onchange=()=>{const t=types[Number(rt.value)]||{};$('ra').value=t.price||0};
}
async function saveRepair(){
  if(!(await requireOpenDay()))return;
  try{const all=await req('repairs'),code='REP-'+new Date().getFullYear()+'-'+String(all.length+1).padStart(4,'0');
  const x={id:uid(),code,date:now(),receivedAt:now(),customer:val('rc'),phone:val('rp'),device:val('rd'),serial:val('rserial'),fault:val('rf'),note:val('rn'),repairType:val('rt'),repairTypeName:(repairTypesList((await req('settings')).find(x=>x.id==='repairTypes')))[Number(val('rt'))]?.name||'',amount:Number(val('ra'))||0,status:'تحت الفحص',decision:'',account:'drawer',paymentRecorded:false};
  if(!x.customer||!x.fault)return toast('الاسم والعطل مطلوبان');await put('repairs',x);await log('استلام صيانة',x);closeModal();toast('تم استلام الجهاز وحفظ تاريخ ووقت الاستلام');render();}catch(e){console.error(e);toast('تعذر حفظ الاستلام')}}

async function repair(v){
  const rs=await req('repairs');const groups={new:rs.filter(r=>r.status==='تحت الفحص'),wait:rs.filter(r=>r.status==='بانتظار العميل'||r.status==='بانتظار التحصيل'),fixed:rs.filter(r=>r.status==='تم الإصلاح'),rejected:rs.filter(r=>r.status==='رفض'),done:rs.filter(r=>r.status==='تم التسليم')};
  const col=(title,a)=>`<div class="stage"><h3>${title} (${a.length})</h3>${a.map(r=>`<div class="job"><b>${esc(r.customer)} • ${esc(r.device)}</b><small>${esc(r.fault)}</small><small>${esc(r.phone||'بدون هاتف')} ${r.serial?'• Serial: '+esc(r.serial):''}</small><small class="repair-date">📅 الاستلام: ${new Date(r.receivedAt||r.date).toLocaleDateString('ar-EG')} — ${new Date(r.receivedAt||r.date).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small>${r.deliveredAt?`<small class="repair-date">📦 التسليم: ${new Date(r.deliveredAt).toLocaleString('ar-EG')}</small>`:''}<div class="age">منذ ${Math.max(0,Math.floor((Date.now()-new Date(r.receivedAt||r.date))/86400000))} يوم</div><div class="actions"><button class="btn mint" onclick="repairAction('${r.id}')">فتح الملف</button>${r.customer?`<button class="btn" onclick="repairProfile('${r.id}')">ملف العميل</button>`:''}</div></div>`).join('')||'<div class="empty">فارغ</div>'}</div>`;
  v.innerHTML=`<div class="page-head"><div><span class="eyebrow">REPAIRS</span><h2>الصيانة والمتابعة</h2><p>استلام واضح، تاريخ كامل، وتسليم من خلال الكاشير.</p></div><div class="head-actions"><button class="btn primary" onclick="newRepair()">＋ استلام جهاز</button><button class="btn ghost" onclick="repairProfileSearch()">👤 ملف عميل</button></div></div><div class="pipeline repair-pipeline">${col('استلام / فحص',groups.new)}${col('بانتظار العميل',groups.wait)}${col('تم الإصلاح',groups.fixed)}${col('رفض',groups.rejected)}${col('تم التسليم',groups.done)}</div>`;
}

async function repairAction(id){const r=(await req('repairs')).find(x=>x.id===id);if(!r)return;const returned=await req('returns');const repairReturns=returned.filter(x=>x.kind==='repair'&&x.repairId===id).reduce((a,x)=>a+Number(x.total||0),0);modal('ملف الصيانة',`<div class="repair-modal-head"><div class="repair-id">${esc(r.code||'REP')}</div><div><b>${esc(r.customer)}</b><p>${esc(r.device)} • ${esc(r.fault)}</p><small>الاستلام: ${new Date(r.receivedAt||r.date).toLocaleString('ar-EG')}</small>${r.deliveredAt?`<small> • التسليم: ${new Date(r.deliveredAt).toLocaleString('ar-EG')}</small>`:''}</div></div><div class="grid two"><div class="card"><div class="kpi"><span>الهاتف</span><b>${esc(r.phone||'—')}</b></div><div class="kpi"><span>Serial</span><b>${esc(r.serial||'—')}</b></div><div class="kpi"><span>نوع الصيانة</span><b>${esc(r.repairTypeName||r.repairType||'—')}</b></div><div class="kpi"><span>الحالة</span><b>${esc(r.status)}</b></div><div class="kpi"><span>قيمة الصيانة</span><b>${money(r.amount)}</b></div><div class="kpi"><span>مرتجع صيانة</span><b>${money(repairReturns)}</b></div><div class="kpi"><span>الملاحظات</span><b>${esc(r.note||'—')}</b></div></div><div class="form"><label>الحالة<select id="rst"><option ${r.status==='تحت الفحص'?'selected':''}>تحت الفحص</option><option ${r.status==='بانتظار العميل'?'selected':''}>بانتظار العميل</option><option ${r.status==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.status==='رفض'?'selected':''}>رفض</option><option ${r.status==='تم التسليم'?'selected':''}>تم التسليم</option></select></label><label>قرار العميل<select id="rdec"><option value="" ${!r.decision?'selected':''}>لم يحدد</option><option ${r.decision==='تم الإصلاح'?'selected':''}>تم الإصلاح</option><option ${r.decision==='رفض'?'selected':''}>رفض</option></select></label><label>قيمة الصيانة<input id="ra" type="number" value="${r.amount||''}"></label><label>حساب التحصيل<select id="repairAccount">${accountOptions(r.account||'drawer')}</select></label><label class="full">ملاحظات<textarea id="rn2">${esc(r.note||'')}</textarea></label></div></div><div class="actions modal-actions">${r.phone?`<button class="btn whatsapp" onclick="whatsapp('${esc(r.phone)}','مرحباً ${esc(r.customer)}، معاك MAGHRABY STORE بخصوص جهاز ${esc(r.device)}. حالة الصيانة الحالية: ${esc(r.status)}.');">WhatsApp</button>`:''}<button class="btn" onclick="repairProfile('${id}')">👤 سجل العميل</button>${r.status==='تم التسليم'&&r.paymentRecorded?`<button class="btn red" onclick="repairReturnNew('${id}')">↩ مرتجع صيانة</button>`:''}<button class="btn primary" onclick="updateRepair('${id}')">حفظ وتحديث</button></div>`)}
async function updateRepair(id){if(!(await requireOpenDay()))return;const r=(await req('repairs')).find(x=>x.id===id);if(!r)return;const old=r.status,newStatus=val('rst');r.decision=val('rdec');r.amount=Number(val('ra'))||0;r.account=val('repairAccount')||'drawer';r.note=val('rn2');if(newStatus==='تم التسليم'&&old!=='تم التسليم'&&r.amount>0&&!r.paymentRecorded){r.status='بانتظار التحصيل';await put('repairs',r);closeModal();if(!state.cart.some(i=>i.repairId===r.id)){state.cart.push({id:'repair:'+r.id,name:'صيانة '+r.device+' — '+r.code,price:r.amount,cost:r.cost||0,qty:1,type:'service',repairId:r.id});}state.saleAccount=r.account||'drawer';state.saleCustomer='';state.saleDepositId='';state.page='sale';toast('تم تحويل الصيانة إلى الكاشير للتحصيل');render();return}r.status=newStatus;if(newStatus==='تم التسليم'&&!r.deliveredAt)r.deliveredAt=now();await put('repairs',r);await log('تحديث صيانة',r);closeModal();toast('تم تحديث الصيانة');render()}

async function repairProfile(id){const r=(await req('repairs')).find(x=>x.id===id);if(!r)return;const all=(await req('repairs')).filter(x=>x.customer===r.customer&&(!r.phone||x.phone===r.phone)).sort((a,b)=>new Date(b.receivedAt||b.date)-new Date(a.receivedAt||a.date));modal('ملف العميل — سجل الصيانة',`<div class="card"><div class="kpi"><span>العميل</span><b>${esc(r.customer)}</b></div><div class="kpi"><span>الهاتف</span><b>${esc(r.phone||'—')}</b></div></div><div class="card table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>الصيانة</th><th>الجهاز</th><th>Serial</th><th>الاستلام</th><th>التسليم</th><th>الحالة</th><th>القيمة</th></tr></thead><tbody>${all.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.device)}</td><td>${esc(x.serial||'—')}</td><td>${new Date(x.receivedAt||x.date).toLocaleString('ar-EG')}</td><td>${x.deliveredAt?new Date(x.deliveredAt).toLocaleString('ar-EG'):'—'}</td><td>${esc(x.status)}</td><td>${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`)}
async function repairProfileSearch(){const rs=await req('repairs');const names=[...new Set(rs.map(x=>x.customer).filter(Boolean))];modal('فتح ملف عميل صيانة',`<div class="form"><label class="full">العميل<select id="rprofile">${names.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label></div><button class="btn primary" style="margin-top:10px" onclick="(async()=>{const n=val('rprofile');const r=(await req('repairs')).find(x=>x.customer===n);if(r){closeModal();repairProfile(r.id)}})()">فتح الملف</button>`) }

async function repairReturnNew(id){if(!(await requireOpenDay()))return;const r=(await req('repairs')).find(x=>x.id===id);if(!r)return;const max=Math.max(0,Number(r.amount||0)- (await req('returns')).filter(x=>x.kind==='repair'&&x.repairId===id).reduce((a,x)=>a+Number(x.total||0),0));if(max<=0)return toast('لا يوجد مبلغ متاح لمرتجع الصيانة');modal('مرتجع صيانة',`<div class="form"><label>الصيانة<input value="${esc(r.code+' — '+r.customer)}" disabled></label><label>المبلغ<input id="rretamt" type="number" min="0" max="${max}" value="${max}"></label><label>حساب رد المبلغ<select id="rretaccount">${accountOptions(r.account||'drawer')}</select></label><label class="full">سبب المرتجع<textarea id="rretreason"></textarea></label></div><button class="btn red" style="margin-top:10px" onclick="saveRepairReturn('${id}')">تسجيل المرتجع</button>`)}
async function saveRepairReturn(id){if(!(await requireOpenDay()))return;const r=(await req('repairs')).find(x=>x.id===id),amount=Number(val('rretamt'))||0;if(!r||amount<=0)return toast('اكتب مبلغًا صحيحًا');const max=Math.max(0,Number(r.amount||0)-(await req('returns')).filter(x=>x.kind==='repair'&&x.repairId===id).reduce((a,x)=>a+Number(x.total||0),0));if(amount>max)return toast('المبلغ أكبر من المتاح للمرتجع');const x={id:uid(),date:now(),kind:'repair',repairId:id,invoiceRef:r.code,itemName:'مرتجع صيانة — '+r.device,qty:1,total:amount,account:val('rretaccount')||'drawer',reason:val('rretreason')};await put('returns',x);await put('cash',{id:uid(),date:x.date,type:'out',amount,account:x.account,reason:'مرتجع صيانة - '+r.code,ref:x.id});await put('invoices',{id:uid(),date:x.date,type:'مرتجع صيانة',total:amount,ref:x.id,account:x.account,note:x.reason});await log('مرتجع صيانة',x);closeModal();toast('تم تسجيل مرتجع الصيانة');render()}

/* Search: live, debounced, and searches products/customers/repairs/invoices. */
let searchTimer;
async function runGlobalSearch(q){q=String(q||'').trim().toLowerCase();const box=$('globalSearchResults');if(!box)return;if(!q){box.innerHTML='';box.classList.add('hidden');return}const [ps,cs,rs,ivs]=await Promise.all([req('products'),req('customers'),req('repairs'),req('invoices')]);const out=[];ps.filter(x=>x.active!==false&&String(x.name).toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push({type:'منتج',label:x.name,sub:money(x.price),page:'sale',q:x.name}));cs.filter(x=>String(x.name).toLowerCase().includes(q)||String(x.phone||'').includes(q)).slice(0,5).forEach(x=>out.push({type:'عميل',label:x.name,sub:x.phone||'',page:'customers',q:x.name}));rs.filter(x=>String(x.customer).toLowerCase().includes(q)||String(x.phone||'').includes(q)||String(x.code||'').toLowerCase().includes(q)||String(x.serial||'').toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push({type:'صيانة',label:x.code+' — '+x.customer,sub:x.device+(x.serial?' • '+x.serial:''),page:'repair',q:x.code}));ivs.filter(x=>String(x.invoiceNo||'').toLowerCase().includes(q)||String(x.customerName||'').toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push({type:'فاتورة',label:x.invoiceNo||x.ref?.slice(0,8),sub:money(x.total),page:'invoices',q:''}));box.innerHTML=out.map((x,i)=>`<button class="search-result" onclick="searchPick(${i})"><b>${esc(x.label)}</b><small>${esc(x.type)} ${x.sub?'• '+esc(x.sub):''}</small></button>`).join('')||'<div class="search-empty">لا توجد نتائج</div>';box._results=out;box.classList.remove('hidden')}
function searchPick(i){const box=$('globalSearchResults'),x=box?._results?.[i];if(!x)return;state.page=x.page;state.q=x.q||'';if(box)box.classList.add('hidden');$('globalSearch').value='';render()}

async function sale(v){const [ps,cs,deposits]=await Promise.all([req('products'),req('customers'),req('deposits')]);let cats=[...new Set(ps.map(p=>p.cat).filter(Boolean))];let q=(state.q||'').toLowerCase();let arr=ps.filter(p=>p.active!==false&&(!state.cat||p.cat===state.cat)&&String(p.name).toLowerCase().includes(q));const openDeposits=deposits.filter(d=>d.status==='open');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">POS • MAGHRABY STORE</span><h2>المبيعات والكاشير</h2><p>بيع أسرع وحساب مالي واضح.</p></div><div class="head-actions"><button class="btn orange" onclick="depositNew()">＋ عربون جهاز</button><button class="btn mint" onclick="settleDepositNew()">تسوية عربون</button><button class="btn ghost" onclick="clearCart()">تفريغ السلة</button><button class="btn primary" onclick="customerNew()">＋ عميل جديد</button></div></div><div class="pos-layout"><section class="card pos-products"><div class="toolbar"><div class="search large"><span>⌕</span><input id="saleSearch" placeholder="ابحث بالاسم أو القسم..." value="${esc(state.q||'')}"></div><div class="chips"><button class="chip ${!state.cat?'active':''}" onclick="state.cat='';render()">الكل</button>${cats.map(c=>`<button class="chip ${state.cat===c?'active':''}" onclick="state.cat='${esc(c)}';render()">${esc(c)}</button>`).join('')}</div></div><div class="product-grid">${arr.map(p=>`<button class="product" data-search="${esc((String(p.name)+" "+String(p.cat||"")).toLowerCase())}" onclick="add('${p.id}')"><div class="pic">${p.image?`<img src="${p.image}" alt="">`:`<span>${p.emoji||'📦'}</span>`}</div><span class="stock ${p.stock<=p.min&&p.type!=='service'?'danger':''}">${p.type==='service'?'خدمة':'متاح '+p.stock}</span><div class="pi"><b>${esc(p.name)}</b><small>${esc(p.cat||'بدون قسم')}</small><strong>${money(p.price)}</strong></div></button>`).join('')||'<div class="empty-state"><div class="empty-icon">📦</div><h2>لا توجد نتائج</h2><p>استخدم البحث أو أضف المنتج من المخزون.</p></div>'}</div></section><section class="card cart pos-cart"><div class="cart-head"><div><span class="eyebrow">CURRENT ORDER</span><h2>السلة</h2></div><span class="cart-count">${state.cart.reduce((a,x)=>a+x.qty,0)} صنف</span></div><div class="form compact"><label>العميل<select id="saleCustomer" onchange="state.saleCustomer=this.value"><option value="">عميل نقدي / بدون تسجيل</option>${cs.map(c=>`<option value="${c.id}" ${state.saleCustomer===c.id?'selected':''}>${esc(c.name)}${c.phone?' • '+esc(c.phone):''}</option>`).join('')}</select></label><label>الحساب<select id="saleAccount" onchange="state.saleAccount=this.value">${accountOptions(state.saleAccount)}</select></label></div><div class="cart-items">${cartHTML()}</div><div class="note"><label>ملاحظة الفاتورة<textarea id="cartNote" oninput="state.cartNote=this.value" placeholder="ملاحظة للفاتورة أو التسليم...">${esc(state.cartNote)}</textarea></label></div><div class="total"><div class="sum"><span>الإجمالي قبل الخصم</span><b>${money(sub())}</b></div><div class="sum"><span>الخصم</span><b class="discount-value">− ${money(state.discount)}</b></div><div class="sum grand"><span>المطلوب</span><span>${money(grand())}</span></div><div class="sum"><span>المدفوع</span><b>${money(grand())}</b></div><div class="sum"><span>المتبقي</span><b>${money(0)}</b></div></div><div class="actions sale-actions"><button class="btn orange" onclick="discount()">خصم</button><button class="btn" onclick="clearCart()">تفريغ السلة</button><button class="btn primary" onclick="saveSale()">حفظ الفاتورة</button></div>${openDeposits.length?`<div class="note"><b>عربونات مفتوحة: ${openDeposits.length}</b><button class="btn" style="margin-top:7px" onclick="settleDepositNew()">تسوية عربون</button></div>`:''}</section></div>`;const inp=$('saleSearch');if(inp)inp.oninput=()=>{state.q=inp.value;const q=String(inp.value||'').toLowerCase().trim();document.querySelectorAll('.product-grid .product').forEach(b=>{b.style.display=!q||String(b.dataset.search||'').includes(q)?'':'none'})};}

function depositNew(){modal('عربون جهاز — إيصال استلام',`<div class="form"><label>اسم العميل<input id="depCustomer"></label><label>الهاتف<input id="depPhone" inputmode="tel"></label><label>الجهاز / المنتج<input id="depProduct" placeholder="PS5 / PS5 Slim / دراع... "></label><label>السعر الأصلي للجهاز<input id="depOriginal" type="number"></label><label>العربون<input id="depAmount" type="number"></label><label>حساب استلام العربون<select id="depAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظات<textarea id="depNote"></textarea></label></div><button class="btn primary" style="margin-top:10px" onclick="saveDeposit()">حفظ العربون وطباعة الإيصال</button>`)}
async function saveDeposit(){if(!(await requireOpenDay()))return;const customer=val('depCustomer'),product=val('depProduct'),original=Number(val('depOriginal'))||0,amount=Number(val('depAmount'))||0;if(!customer||!product||original<=0||amount<=0||amount>original)return toast('راجع بيانات العربون والمبلغ');const x={id:uid(),date:now(),customerName:customer,customerPhone:val('depPhone'),productName:product,originalPrice:original,amount,account:val('depAccount')||'drawer',note:val('depNote'),status:'open'};await put('deposits',x);await put('cash',{id:uid(),date:x.date,type:'in',amount,account:x.account,reason:'عربون جهاز',ref:x.id,note:x.note});await put('invoices',{id:uid(),date:x.date,type:'عربون جهاز',total:amount,ref:x.id,invoiceNo:'DEP-'+x.id.slice(0,8).toUpperCase(),account:x.account,customerName:x.customerName,customerPhone:x.customerPhone,note:x.note});await log('استلام عربون جهاز',x);closeModal();toast('تم تسجيل العربون');printDepositReceipt(x);render()}
async function settleDepositNew(){const ds=(await req('deposits')).filter(x=>x.status==='open');if(!ds.length)return toast('لا توجد عربونات مفتوحة');modal('تسوية عربون — بيع الجهاز',`<div class="form"><label class="full">العربون<select id="settleDep">${ds.map(x=>`<option value="${x.id}">${esc(x.customerName)} • ${esc(x.productName)} • عربون ${money(x.amount)} • السعر ${money(x.originalPrice)}</option>`).join('')}</select></label><label>حساب تحصيل الباقي<select id="settleAccount">${accountOptions('drawer')}</select></label></div><p class="muted" style="margin-top:10px">سيتم تسجيل سعر الجهاز كاملًا كإيراد بيع، لكن الخزنة ستستقبل الباقي فقط لأن العربون دخل سابقًا.</p><button class="btn primary" style="margin-top:10px" onclick="settleDepositToCart()">إضافة للتسوية في الكاشير</button>`)}
async function settleDepositToCart(){const d=(await req('deposits')).find(x=>x.id===val('settleDep'));if(!d)return;const remaining=Math.max(0,Number(d.originalPrice)-Number(d.amount));state.cart.push({id:'deposit:'+d.id,name:d.productName+' — تسوية عربون',price:remaining,cost:0,qty:1,type:'depositSettlement',depositId:d.id,originalPrice:d.originalPrice,depositAmount:d.amount,customerName:d.customerName,customerPhone:d.customerPhone});state.saleAccount=val('settleAccount')||'drawer';state.saleCustomer='';state.depositSettlementId=d.id;closeModal();state.page='sale';toast('تمت إضافة تسوية العربون إلى الكاشير — الباقي فقط سيدخل الخزنة');render()}
async function saveSale(){if(!(await requireOpenDay()))return;if(!state.cart.length)return toast('السلة فاضية');try{const [products,customers,repairs,deposits]=await Promise.all([req('products'),req('customers'),req('repairs'),req('deposits')]);const customer=customers.find(c=>c.id===state.saleCustomer);const depositItem=state.cart.find(i=>i.depositId);const total=grand();if(depositItem){const d=deposits.find(x=>x.id===depositItem.depositId);if(!d||d.status!=='open')throw new Error('العربون غير متاح');}
for(const i of state.cart){if(i.repairId||i.type==='depositSettlement')continue;const p=products.find(p=>p.id===i.id);if(!p)throw new Error('المنتج غير موجود');if(p.type!=='service'&&Number(i.qty)>Number(p.stock||0))throw new Error('المخزون غير كافٍ للصنف: '+p.name)}
const originalDevice=depositItem?Number(depositItem.originalPrice):0;const revenue=depositItem?originalDevice:total;const invoiceNo='INV-'+new Date().getFullYear()+'-'+String((await req('invoices')).length+1).padStart(5,'0');const saleItems=state.cart.map(i=>({...i}));const x={id:uid(),invoiceNo,date:now(),items:saleItems,subtotal:depositItem?originalDevice:sub(),discount:depositItem?0:state.discount,total:revenue,cashReceived:total,remaining:depositItem?0:Math.max(0,revenue-total),account:state.saleAccount,customerId:customer?.id||depositItem?.depositId||'',customerName:customer?.name||depositItem?.customerName||'',customerPhone:customer?.phone||depositItem?.customerPhone||'',depositId:depositItem?.depositId||'',depositAmount:depositItem?.depositAmount||0,note:state.cartNote};const inv={id:uid(),date:x.date,type:'بيع',total:revenue,ref:x.id,invoiceNo,note:x.note,account:x.account,customerId:x.customerId,customerName:x.customerName,customerPhone:x.customerPhone,cashReceived:x.cashReceived,remaining:x.remaining,depositAmount:x.depositAmount};const cashRow={id:uid(),date:x.date,type:'in',amount:total,account:x.account,reason:depositItem?'تسوية عربون جهاز':'بيع',ref:x.id,note:x.note};await new Promise((resolve,reject)=>{const tx=db.transaction(['sales','invoices','cash','products','repairs','stockMoves','deposits'],'readwrite');tx.objectStore('sales').put(x);tx.objectStore('invoices').put(inv);tx.objectStore('cash').put(cashRow);for(const i of x.items){if(i.repairId){const rr=repairs.find(z=>z.id===i.repairId);if(rr){rr.status='تم التسليم';rr.deliveredAt=x.date;rr.paymentRecorded=true;rr.paymentInvoiceId=x.id;tx.objectStore('repairs').put(rr)}}else if(i.type!=='depositSettlement'){const p=products.find(p=>p.id===i.id);if(p&&p.type!=='service'){const before=Number(p.stock);p.stock=Math.max(0,before-i.qty);tx.objectStore('products').put(p);tx.objectStore('stockMoves').put({id:uid(),date:x.date,productId:p.id,product:p.name,qty:-i.qty,before,after:p.stock,reason:'بيع',ref:x.id})}}}if(depositItem){const d=deposits.find(z=>z.id===depositItem.depositId);d.status='settled';d.settledAt=x.date;d.settlementSaleId=x.id;tx.objectStore('deposits').put(d)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('فشل حفظ الفاتورة'));tx.onabort=()=>reject(tx.error||new Error('تم إلغاء الحفظ'))});await log('بيع',x);state.lastInvoice=x;clearCart();state.saleAccount='drawer';state.saleCustomer='';state.depositSettlementId='';toast('تم حفظ الفاتورة وتسجيل التحصيل بنجاح');render()}catch(e){console.error(e);toast(e.message||'فشل حفظ الفاتورة — لم يتم تغيير السلة')}}

