async function reports(v){const [sales,repairs,expenses,cashRows,purchases,returnsRows,days]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('purchases'),req('returns'),req('days')]);const d=today(),dt=new Date();const sum=(a)=>a.reduce((z,x)=>z+Number(x||0),0);const inRange=(rows,start,end=dt)=>rows.filter(x=>{const q=new Date(x.date);return q>=start&&q<=end});const ranges={week:new Date(dt.getFullYear(),dt.getMonth(),dt.getDate()-6),month:new Date(dt.getFullYear(),dt.getMonth(),1),year:new Date(dt.getFullYear(),0,1)};const saleClass=(arr)=>{let product=0,repair=0,cogs=0,discount=0;for(const x of arr){discount+=Number(x.discount||0);for(const i of (x.items||[])){const v=Number(i.price||0)*Number(i.qty||0);if(i.repairId)repair+=v;else if(i.type!=='depositSettlement') {product+=v;cogs+=Number(i.cost||0)*Number(i.qty||0)}}if(x.depositId)repair=repair; }return {product,repair,cogs,discount}};const cashSum=rows=>({in:sum(rows.filter(x=>x.type==='in'&&!x.transfer).map(x=>x.amount)),out:sum(rows.filter(x=>x.type==='out'&&!x.transfer).map(x=>x.amount))});const makeRange=start=>{const sr=inRange(sales,start),cr=inRange(cashRows,start),er=inRange(expenses,start),pr=inRange(purchases,start),rr=inRange(returnsRows,start);const sc=saleClass(sr),cs=cashSum(cr),expenseTotal=sum(er.map(x=>x.amount)),purchaseTotal=sum(pr.map(x=>x.total)),returnTotal=sum(rr.map(x=>x.total));return {sales:sc.product,repairs:sc.repair,cogs:sc.cogs,discount:sc.discount,income:cs.in,out:cs.out,expenses:expenseTotal,purchases:purchaseTotal,returns:returnTotal,netProfit:sc.product+sc.repair-sc.cogs-expenseTotal-returnTotal}};const R={week:makeRange(ranges.week),month:makeRange(ranges.month),year:makeRange(ranges.year),day:makeRange(new Date(dt.getFullYear(),dt.getMonth(),dt.getDate()))};const B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));const day=days.find(x=>x.date===d);v.innerHTML=`<div class="page-head"><div><span class="eyebrow">REPORTS</span><h2>التقارير والحسابات</h2><p>الدخل والخرج والربح والصيانة والمبيعات والحسابات في مكان واحد.</p></div><div class="head-actions"><button class="btn dark" onclick="window.print()">طباعة / حفظ PDF</button>${day?.closedAt?'':`<button class="btn primary" onclick="closeDay()">إقفال اليوم</button>`}</div></div><div class="grid stats">${stat('دخل اليوم',R.day.income,'كل الداخل غير التحويلات')}${stat('خرج اليوم',R.day.out,'كل الخارج غير التحويلات')}${stat('صافي اليوم',R.day.income-R.day.out,'حركة نقدية')}${stat('ربح اليوم',R.day.netProfit,'مبيعات + صيانة − تكلفة − مصروفات − مرتجعات')}</div><div class="grid three"><div class="card"><h3>هذا الأسبوع</h3>${reportCard(R.week)}</div><div class="card"><h3>هذا الشهر</h3>${reportCard(R.month)}</div><div class="card"><h3>هذه السنة</h3>${reportCard(R.year)}</div></div><div class="section"><h2>تفصيل الحسابات — اليوم</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>الحساب</th><th>الرصيد المتوقع</th><th>دخل</th><th>خرج</th></tr></thead><tbody>${ACCOUNTS.map((a,i)=>`<tr><td>${a[1]}</td><td>${money(B[i].expected)}</td><td>${money(B[i].inc)}</td><td>${money(B[i].out)}</td></tr>`).join('')}</tbody></table></div><div class="section"><h2>تفصيل النشاط</h2></div><div class="grid four"><div class="card kpi"><span>مبيعات المنتجات</span><b>${money(R.day.sales)}</b></div><div class="card kpi"><span>دخل الصيانة</span><b>${money(R.day.repairs)}</b></div><div class="card kpi"><span>المشتريات</span><b>${money(R.day.purchases)}</b></div><div class="card kpi"><span>مصروفات المحل</span><b>${money(R.day.expenses)}</b></div><div class="card kpi"><span>المرتجعات</span><b>${money(R.day.returns)}</b></div><div class="card kpi"><span>الخصومات</span><b>${money(R.day.discount)}</b></div><div class="card kpi"><span>عدد الصيانات المسلّمة</span><b>${repairs.filter(x=>x.deliveredAt&&x.deliveredAt.slice(0,10)===d).length} جهاز</b></div><div class="card kpi"><span>اليوم</span><b>${day?.closedAt?'مقفل':'مفتوح'}</b></div></div><div class="section"><h2>مراجعة التاريخ</h2></div><div class="card"><div class="form compact"><label>السنة<select id="historyYear"></select></label><label>الشهر<select id="historyMonth"><option value="all">كل الشهور</option><option value="01">يناير</option><option value="02">فبراير</option><option value="03">مارس</option><option value="04">أبريل</option><option value="05">مايو</option><option value="06">يونيو</option><option value="07">يوليو</option><option value="08">أغسطس</option><option value="09">سبتمبر</option><option value="10">أكتوبر</option><option value="11">نوفمبر</option><option value="12">ديسمبر</option></select></label></div><div id="historyResult" class="history-result"></div></div>`;initHistory()}
function reportCard(x){return `<div class="kpi"><span>الدخل</span><b>${money(x.income)}</b></div><div class="kpi"><span>الخرج</span><b>${money(x.out)}</b></div><div class="kpi"><span>المبيعات</span><b>${money(x.sales)}</b></div><div class="kpi"><span>الصيانة</span><b>${money(x.repairs)}</b></div><div class="kpi"><span>المصروفات</span><b>${money(x.expenses)}</b></div><div class="kpi"><span>المشتريات</span><b>${money(x.purchases)}</b></div><div class="kpi"><span>المرتجعات</span><b>${money(x.returns)}</b></div><div class="kpi"><span>الخصومات</span><b>${money(x.discount)}</b></div><div class="kpi"><span>صافي الربح التقريبي</span><b class="${x.netProfit>=0?'positive':'negative'}">${money(x.netProfit)}</b></div>`}

async function historyRefresh(){const y=$('historyYear')?.value,m=$('historyMonth')?.value,rows=(await cashAll()).filter(x=>{const d=new Date(x.date);return String(d.getFullYear())===y&&(m==='all'||String(d.getMonth()+1).padStart(2,'0')===m)}),inc=rows.filter(x=>x.type==='in'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0),out=rows.filter(x=>x.type==='out'&&!x.transfer).reduce((a,x)=>a+Number(x.amount||0),0);const by=Object.fromEntries(ACCOUNTS.map(a=>[a[0],{in:0,out:0}]));rows.forEach(x=>{if(by[x.account]&&!x.transfer)by[x.account][x.type]+=Number(x.amount||0)});const el=$('historyResult');if(el)el.innerHTML=`<div class="grid four"><div class="card kpi"><span>إجمالي الداخل</span><b class="positive">${money(inc)}</b></div><div class="card kpi"><span>إجمالي الخارج</span><b class="negative">${money(out)}</b></div><div class="card kpi"><span>صافي الحركة</span><b>${money(inc-out)}</b></div><div class="card kpi"><span>عدد الحركات</span><b>${rows.length}</b></div></div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>الحساب</th><th>الدخل</th><th>الخرج</th><th>الصافي</th></tr></thead><tbody>${ACCOUNTS.map(a=>`<tr><td>${a[1]}</td><td>${money(by[a[0]].in)}</td><td>${money(by[a[0]].out)}</td><td>${money(by[a[0]].in-by[a[0]].out)}</td></tr>`).join('')}</tbody></table></div>`}

async function initHistory(){const years=new Set([String(new Date().getFullYear())]);for(const store of ['cash','sales','repairs','expenses','purchases','invoices','deposits'])for(const x of await req(store)){if(x.date)years.add(String(new Date(x.date).getFullYear()))}const ys=[...years].sort((a,b)=>b.localeCompare(a));const y=$('historyYear');if(!y)return;y.innerHTML=ys.map(v=>`<option value="${v}">${v}</option>`).join('');y.value=String(new Date().getFullYear());$('historyMonth').value='all';y.onchange=historyRefresh;$('historyMonth').onchange=historyRefresh;historyRefresh()}

async function cashNew(type){if(!(await requireOpenDay()))return;const opts=type==='in'?['دخل آخر','تحصيل','عربون','استرداد من مورد','أخرى']:['سلفة موظف','إيجار','كهرباء','مياه','معطر واستهلاك','نقل','أخرى'];modal(type==='in'?'دخل جديد':'خرج جديد',`<div class="form"><label>الحساب<select id="cashAccount">${accountOptions('drawer')}</select></label><label>المبلغ<input id="ca" type="number"></label><label>البيان<select id="cr">${opts.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="full">ملاحظة<textarea id="cn"></textarea></label></div><button class="btn ${type==='in'?'mint':'red'}" style="margin-top:11px" onclick="saveCash('${type}')">حفظ</button>`)}
