async function saveExpense(){if(!(await requireOpenDay()))return;const a=Number(val('ea'))||0;if(!a)return toast('اكتب المبلغ');const x={id:uid(),date:now(),type:val('et'),amount:a,note:val('en'),account:val('expenseAccount')||'drawer'};await put('expenses',x);await put('cash',{id:uid(),date:x.date,type:'out',amount:a,account:x.account,reason:x.type,ref:x.id,note:x.note});await log('مصروف',x);closeModal();toast('تم تسجيل المصروف');render()}

