/* Footer and app identity */

/* Correct report classification: repair revenue is not product sales, and deposit settlement records the full device revenue while collecting only the remainder. */
function classifySale(x){
  let grossProduct=0,grossRepair=0,cogs=0;
  for(const i of (x.items||[])){
    const v=Number(i.price||0)*Number(i.qty||0);
    if(i.repairId) grossRepair+=v;
    else if(i.type==='depositSettlement') { /* represented by x.total below */ }
    else { grossProduct+=v;cogs+=Number(i.cost||0)*Number(i.qty||0); }
  }
  if(x.depositId){grossProduct=Number(x.total||0);cogs=0;}
  const gross=grossProduct+grossRepair;
  const discount=Number(x.discount||0);
  const factor=gross>0?Math.max(0,(gross-discount)/gross):1;
  return {product:grossProduct*factor,repair:grossRepair*factor,cogs:cogs*factor,discount};
}

async function reports(v){
  const [sales,repairs,expenses,cashRows,purchases,returnsRows,days]=await Promise.all([req('sales'),req('repairs'),req('expenses'),cashAll(),req('purchases'),req('returns'),req('days')]);
  const d=today(),nowDate=new Date();
  const sum=a=>a.reduce((z,x)=>z+Number(x||0),0);
  const rangeRows=(rows,start)=>rows.filter(x=>{const q=new Date(x.date);return q>=start&&q<=nowDate});
  const ranges={week:new Date(nowDate.getFullYear(),nowDate.getMonth(),nowDate.getDate()-6),month:new Date(nowDate.getFullYear(),nowDate.getMonth(),1),year:new Date(nowDate.getFullYear(),0,1),day:new Date(nowDate.getFullYear(),nowDate.getMonth(),nowDate.getDate())};
  const cashSum=rows=>({in:sum(rows.filter(x=>x.type==='in'&&!x.transfer).map(x=>x.amount)),out:sum(rows.filter(x=>x.type==='out'&&!x.transfer).map(x=>x.amount))});
  const makeRange=start=>{const ss=rangeRows(sales,start),cc=rangeRows(cashRows,start),ee=rangeRows(expenses,start),pp=rangeRows(purchases,start),rr=rangeRows(returnsRows,start);let product=0,repair=0,cogs=0,discount=0;ss.forEach(x=>{const z=classifySale(x);product+=z.product;repair+=z.repair;cogs+=z.cogs;discount+=z.discount});const cs=cashSum(cc),expenseTotal=sum(ee.map(x=>x.amount)),purchaseTotal=sum(pp.map(x=>x.total)),returnTotal=sum(rr.map(x=>x.total));return {sales:product,repairs:repair,cogs,discount,income:cs.in,out:cs.out,expenses:expenseTotal,purchases:purchaseTotal,returns:returnTotal,netProfit:product+repair-cogs-expenseTotal-returnTotal}};
  const R={day:makeRange(ranges.day),week:makeRange(ranges.week),month:makeRange(ranges.month),year:makeRange(ranges.year)};
  const B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0])));const day=days.find(x=>x.date===d);
  v.innerHTML=`<div class="page-head"><div><span class="eyebrow">REPORTS • FINANCE</span><h2>التقارير والحسابات</h2><p>تقارير صحيحة بدون تكرار دخل الصيانة أو التحويلات.</p></div><div class="head-actions"><button class="btn dark" onclick="window.print()">طباعة / حفظ PDF</button>${day?.closedAt?'':`<button class="btn primary" onclick="closeDay()">إقفال اليوم</button>`}</div></div>
  <div class="grid stats">${stat('دخل اليوم',R.day.income,'الداخل الفعلي غير التحويلات')}${stat('خرج اليوم',R.day.out,'الخارج الفعلي غير التحويلات')}${stat('صافي الحركة',R.day.income-R.day.out,'دخل − خرج')}${stat('ربح اليوم',R.day.netProfit,'مبيعات + صيانة − التكلفة − المصروفات − المرتجعات')}</div>
  <div class="grid three"><div class="card"><h3>الأسبوع الحالي</h3>${reportCard(R.week)}</div><div class="card"><h3>الشهر الحالي</h3>${reportCard(R.month)}</div><div class="card"><h3>السنة الحالية</h3>${reportCard(R.year)}</div></div>
  <div class="section"><h2>أرصدة الحسابات اليوم</h2></div><div class="card table-wrap"><table class="table"><thead><tr><th>الحساب</th><th>بداية</th><th>دخل</th><th>خرج</th><th>المتوقع الآن</th></tr></thead><tbody>${ACCOUNTS.map((a,i)=>`<tr><td>${a[1]}</td><td>${money(B[i].opening)}</td><td>${money(B[i].inc)}</td><td>${money(B[i].out)}</td><td>${money(B[i].expected)}</td></tr>`).join('')}</tbody></table></div>
  <div class="section"><h2>تحليل النشاط اليومي</h2></div><div class="grid four"><div class="card kpi"><span>مبيعات المنتجات</span><b>${money(R.day.sales)}</b></div><div class="card kpi"><span>دخل الصيانة</span><b>${money(R.day.repairs)}</b></div><div class="card kpi"><span>المشتريات</span><b>${money(R.day.purchases)}</b></div><div class="card kpi"><span>مصروفات المحل</span><b>${money(R.day.expenses)}</b></div><div class="card kpi"><span>المرتجعات</span><b>${money(R.day.returns)}</b></div><div class="card kpi"><span>الخصومات</span><b>${money(R.day.discount)}</b></div><div class="card kpi"><span>الصيانات المسلّمة</span><b>${repairs.filter(x=>x.deliveredAt&&x.deliveredAt.slice(0,10)===d).length} جهاز</b></div><div class="card kpi"><span>حالة اليوم</span><b>${day?.closedAt?'مقفل':'مفتوح'}</b></div></div>
  <div class="section"><h2>مراجعة أي سنة / شهر</h2></div><div class="card"><div class="form compact"><label>السنة<select id="historyYear"></select></label><label>الشهر<select id="historyMonth"><option value="all">كل الشهور</option><option value="01">يناير</option><option value="02">فبراير</option><option value="03">مارس</option><option value="04">أبريل</option><option value="05">مايو</option><option value="06">يونيو</option><option value="07">يوليو</option><option value="08">أغسطس</option><option value="09">سبتمبر</option><option value="10">أكتوبر</option><option value="11">نوفمبر</option><option value="12">ديسمبر</option></select></label></div><div id="historyResult" class="history-result"></div></div>`;
  initHistory();
}

async function returns(v){const rs=await req('returns');v.innerHTML=`<div class="page-head"><div><span class="eyebrow">RETURNS</span><h2>المرتجعات</h2><p>مرتجعات البيع والصيانة مع رد المبلغ من الحساب الصحيح.</p></div><div class="head-actions"><button class="btn red" onclick="returnNew()">＋ مرتجع بيع</button><button class="btn orange" onclick="repairReturnPicker()">＋ مرتجع صيانة</button></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>النوع</th><th>المرجع</th><th>العميل/الصنف</th><th>المبلغ</th><th>الحساب</th><th>السبب</th></tr></thead><tbody>${rs.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${new Date(x.date).toLocaleString('ar-EG')}</td><td>${x.kind==='repair'?'مرتجع صيانة':'مرتجع بيع'}</td><td>${esc(x.invoiceRef||'—')}</td><td>${esc(x.itemName||'—')}</td><td>${money(x.total)}</td><td>${accountName(x.account)}</td><td>${esc(x.reason||'')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد مرتجعات</td></tr>'}</tbody></table></div>`}
async function repairReturnPicker(){const rs=(await req('repairs')).filter(r=>r.status==='تم التسليم'&&r.paymentRecorded);if(!rs.length)return toast('لا توجد صيانات مسلّمة ومدفوعة');modal('اختيار صيانة لمرتجع',`<div class="form"><label class="full">الصيانة<select id="rrrepair">${rs.map(r=>`<option value="${r.id}">${esc(r.code)} • ${esc(r.customer)} • ${esc(r.device)} • ${money(r.amount)}</option>`).join('')}</select></label></div><button class="btn red" style="margin-top:10px" onclick="(async()=>{const id=val('rrrepair');closeModal();repairReturnNew(id)})()">متابعة</button>`)}

// Prevent accidental operations after closing a day; opening the next day starts from the previous counted balances.
async function saveDay(d){if(d!==today())return toast('يمكن إقفال اليوم الحالي فقط');const B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),x={id:d,date:d,note:val('dn'),closedAt:now(),status:'closed'};ACCOUNTS.forEach((a,i)=>{const counted=Number(val('count_'+a[0]))||0;x[a[0]+'Opening']=B[i].opening;x[a[0]+'Expected']=B[i].expected;x[a[0]+'Counted']=counted;x[a[0]+'Difference']=counted-B[i].expected});x.expected=x.drawerExpected;x.counted=x.drawerCounted;x.difference=x.drawerDifference;await put('days',x);closeModal();toast('تم إقفال اليوم وترحيل الأرصدة لليوم التالي');updateDayButton();render()}

// Live search hook
(function installSearch(){const gs=$('globalSearch');if(!gs)return;gs.oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>runGlobalSearch(gs.value),180)};gs.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();runGlobalSearch(gs.value)}};document.addEventListener('click',e=>{const w=e.target.closest('.header-search-wrap');if(!w){const box=$('globalSearchResults');if(box)box.classList.add('hidden')}})})();

/* Correct number units on dashboard/stat cards. */
function stat(label,n,sub=''){const isCount=/عدد|أجهزة|جهاز|عملاء|عمليات|فواتير|أصناف/.test(String(label));const value=isCount?`${new Intl.NumberFormat('ar-EG').format(Number(n)||0)} ${String(label).includes('أجهزة')||String(label).includes('جهاز')?'جهاز':''}`:money(n);return `<div class="card stat"><div class="label">${label}</div><div class="num">${value}</div><div class="sub">${sub}</div></div>`}

async function dashboard(v){const [s,r,e,p]=await Promise.all([req('sales'),req('repairs'),req('expenses'),req('products')]);const d=today(),sd=s.filter(x=>x.date.slice(0,10)===d),ed=e.filter(x=>x.date.slice(0,10)===d),pending=r.filter(x=>x.status!=='تم التسليم'),low=p.filter(x=>x.type!=='service'&&Number(x.stock)<=Number(x.min)&&Number(x.min)>0),B=await Promise.all(ACCOUNTS.map(a=>balanceFor(d,a[0]))),cogs=sd.reduce((a,x)=>a+(x.items||[]).reduce((z,i)=>z+Number(i.cost||0)*Number(i.qty||0),0),0),productSales=sd.reduce((a,x)=>a+classifySale(x).product,0),profit=productSales-cogs-ed.reduce((a,x)=>a+Number(x.amount||0),0),day=await dayRecord(d);v.innerHTML=`<div class="grid stats">${stat('مبيعات اليوم',productSales,'بعد الخصومات')}${stat('دخل اليوم',B[0].inc,'كل حركات الداخل')}${stat('خرج اليوم',B[0].out,'كل حركات الخارج')}${stat('المتوقع في الدرج',B[0].expected,'رصيد بداية + الداخل − الخارج')}${stat('المحفظة',B[1].expected,'رصيد جارٍ')}${stat('InstaPay',B[2].expected,'رصيد جارٍ')}${stat('ربح تقريبي',profit,'مبيعات المنتجات − التكلفة − المصروفات')}${stat('أجهزة معلقة',pending.length,'وحدة عدد وليست قيمة مالية')}</div><div class="hero card"><div><span class="eyebrow">MAGHRABY STORE • مركز التشغيل</span><h2>${day?.closedAt?'اليوم مقفول':'جاهز تبدأ شغل اليوم؟'}</h2><p>${day?.closedAt?'يمكنك مراجعة التقارير والفواتير والتاريخ، وفتح يوم جديد في اليوم التالي.':'أضف المنتجات والخدمات ثم ابدأ تسجيل عمليات اليوم.'}</p></div>${day?.closedAt?'':`<button class="btn primary hero-btn" data-page="sale">＋ ابدأ البيع</button>`}</div><div class="section"><h2>مركز العمل</h2></div><div class="grid quick"><button data-page="sale">🛒<b>بيع جديد</b><small>سلة + خصم + فاتورة</small></button><button data-page="repair">🔧<b>استلام صيانة</b><small>جهاز + Serial + تاريخ الاستلام</small></button><button data-page="cash">💵<b>حركة مالية</b><small>دخل / خرج / تحويل</small></button><button data-page="purchases">📦<b>شراء بضاعة</b><small>يزود المخزون ويحسب التكلفة</small></button><button data-page="reports">📊<b>التقارير</b><small>دخل + خرج + ربح + إقفال اليوم</small></button></div><div class="grid two"><div><div class="section"><h2>⚠ يحتاج انتباه</h2></div><div class="card">${low.length?low.map(x=>`<div class="kpi"><span>📦 ${esc(x.name)}<small> — الموجود ${x.stock}</small></span><b class="negative">اطلب الآن</b></div>`).join(''):'<div class="empty">المخزون الأساسي جيد 🎉</div>'}</div></div><div><div class="section"><h2>🔧 الصيانة</h2></div><div class="card">${pending.slice(0,5).map(x=>`<div class="kpi"><span><b>${esc(x.customer)}</b> — ${esc(x.device)}<small> ${esc(x.fault)}</small></span><b class="negative">${Math.floor((Date.now()-new Date(x.receivedAt||x.date))/86400000)} يوم</b></div>`).join('')||'<div class="empty">لا توجد أجهزة معلقة</div>'}</div></div></div>`}

/* Deposit flow: support real stock products when available, while keeping the advance out of sales revenue until final settlement. */
async function depositNew(){if(!(await requireOpenDay()))return;const ps=(await req('products')).filter(p=>p.type!=='service'&&p.active!==false);modal('عربون جهاز — إيصال استلام',`<div class="form"><label>اسم العميل<input id="depCustomer"></label><label>الهاتف<input id="depPhone" inputmode="tel"></label><label class="full">الجهاز / المنتج<select id="depProduct">${ps.map(p=>`<option value="${p.id}" data-price="${Number(p.price)||0}">${esc(p.name)} — ${money(p.price)}</option>`).join('')}<option value="custom">جهاز / منتج آخر</option></select></label><label id="depCustomWrap" class="full hidden">اسم الجهاز<input id="depCustomProduct"></label><label>السعر الأصلي للجهاز<input id="depOriginal" type="number"></label><label>العربون<input id="depAmount" type="number"></label><label>حساب استلام العربون<select id="depAccount">${accountOptions('drawer')}</select></label><label class="full">ملاحظات<textarea id="depNote"></textarea></label></div><button class="btn primary" style="margin-top:10px" onclick="saveDeposit()">حفظ العربون وطباعة الإيصال</button>`);const sel=$('depProduct');const sync=()=>{const opt=sel?.selectedOptions?.[0];if(!opt)return;const custom=sel.value==='custom';$('depCustomWrap')?.classList.toggle('hidden',!custom);if(!custom)$('depOriginal').value=opt.dataset.price||'';};sel.onchange=sync;sync()}
async function saveDeposit(){if(!(await requireOpenDay()))return;const customer=val('depCustomer'),phone=val('depPhone'),sel=$('depProduct'),productId=sel?.value==='custom'?'':(sel?.value||''),productName=sel?.value==='custom'?val('depCustomProduct'):(sel?.selectedOptions?.[0]?.textContent?.split(' — ')[0]||''),original=Number(val('depOriginal'))||0,amount=Number(val('depAmount'))||0;if(!customer||!productName||original<=0||amount<=0||amount>original)return toast('راجع بيانات العربون والمبلغ');const x={id:uid(),date:now(),customerName:customer,customerPhone:phone,productId,productName,originalPrice:original,amount,account:val('depAccount')||'drawer',note:val('depNote'),status:'open'};await put('deposits',x);await put('cash',{id:uid(),date:x.date,type:'in',amount,account:x.account,reason:'عربون جهاز',ref:x.id,note:x.note});await put('invoices',{id:uid(),date:x.date,type:'عربون جهاز',total:amount,ref:x.id,invoiceNo:'DEP-'+x.id.slice(0,8).toUpperCase(),account:x.account,customerName:x.customerName,customerPhone:x.customerPhone,cashReceived:amount,remaining:0,note:x.note});await log('استلام عربون جهاز',x);closeModal();toast('تم تسجيل العربون وطباعة إيصال الاستلام');printDepositReceipt(x);render()}
async function settleDepositToCart(){const d=(await req('deposits')).find(x=>x.id===val('settleDep'));if(!d)return;const remaining=Math.max(0,Number(d.originalPrice)-Number(d.amount));const p=d.productId?(await req('products')).find(x=>x.id===d.productId):null;if(p&&Number(p.stock||0)<1)return toast('الجهاز المرتبط بالعربون غير متوفر في المخزون');const item={id:p?.id||('deposit:'+d.id),name:(p?.name||d.productName)+' — تسوية عربون',price:remaining,cost:Number(p?.cost||0),qty:1,type:p?'depositSettlement':'depositSettlement',depositId:d.id,originalPrice:d.originalPrice,depositAmount:d.amount,customerName:d.customerName,customerPhone:d.customerPhone,productId:p?.id||''};state.cart.push(item);state.saleAccount=val('settleAccount')||'drawer';state.saleCustomer='';state.depositSettlementId=d.id;closeModal();state.page='sale';toast('تمت إضافة تسوية العربون إلى الكاشير — الباقي فقط سيدخل الخزنة');render()}
async function saveSale(){if(!(await requireOpenDay()))return;if(!state.cart.length)return toast('السلة فاضية');try{const [products,customers,repairs,deposits]=await Promise.all([req('products'),req('customers'),req('repairs'),req('deposits')]);const customer=customers.find(c=>c.id===state.saleCustomer);const depositItem=state.cart.find(i=>i.depositId);if(state.cart.filter(i=>i.depositId).length>1)throw new Error('لا يمكن تسوية أكثر من عربون في فاتورة واحدة');const grossOthers=state.cart.filter(i=>!i.depositId).reduce((a,i)=>a+Number(i.price||0)*Number(i.qty||0),0);const deviceGross=depositItem?Number(depositItem.originalPrice||0):0;const grossSubtotal=deviceGross+grossOthers;const discount=depositItem?Number(state.discount||0):Number(state.discount||0);const total=depositItem?Math.max(0,grossSubtotal-discount):Math.max(0,grossSubtotal-discount);if(depositItem){const d=deposits.find(x=>x.id===depositItem.depositId);if(!d||d.status!=='open')throw new Error('العربون غير متاح');}
for(const i of state.cart){if(i.repairId||i.depositId)continue;const p=products.find(p=>p.id===i.id);if(!p)throw new Error('المنتج غير موجود');if(p.type!=='service'&&Number(i.qty)>Number(p.stock||0))throw new Error('المخزون غير كافٍ للصنف: '+p.name)}
if(depositItem?.productId){const p=products.find(x=>x.id===depositItem.productId);if(!p||Number(p.stock||0)<1)throw new Error('الجهاز المرتبط بالعربون غير متوفر في المخزون');}
const cashDue=depositItem?Math.max(0,Number(depositItem.originalPrice)-Number(depositItem.depositAmount||0)+grossOthers-Number(state.discount||0)):total;const invoiceNo='INV-'+new Date().getFullYear()+'-'+String((await req('invoices')).length+1).padStart(5,'0');const saleItems=state.cart.map(i=>({...i}));const repairGross=state.cart.filter(i=>i.repairId).reduce((a,i)=>a+Number(i.price||0)*Number(i.qty||0),0);const x={id:uid(),invoiceNo,date:now(),items:saleItems,subtotal:grossSubtotal,discount,total,cashReceived:cashDue,remaining:0,account:state.saleAccount,customerId:customer?.id||'',customerName:customer?.name||depositItem?.customerName||'',customerPhone:customer?.phone||depositItem?.customerPhone||'',depositId:depositItem?.depositId||'',depositAmount:depositItem?.depositAmount||0,note:state.cartNote};const inv={id:uid(),date:x.date,type:'بيع',total:x.total,ref:x.id,invoiceNo,note:x.note,account:x.account,customerId:x.customerId,customerName:x.customerName,customerPhone:x.customerPhone,cashReceived:x.cashReceived,remaining:x.remaining,depositAmount:x.depositAmount};const cashRow={id:uid(),date:x.date,type:'in',amount:cashDue,account:x.account,reason:depositItem?'تسوية عربون جهاز':'بيع',ref:x.id,note:x.note};await new Promise((resolve,reject)=>{const tx=db.transaction(['sales','invoices','cash','products','repairs','stockMoves','deposits'],'readwrite');tx.objectStore('sales').put(x);tx.objectStore('invoices').put(inv);tx.objectStore('cash').put(cashRow);for(const i of x.items){if(i.repairId){const rr=repairs.find(z=>z.id===i.repairId);if(rr){rr.status='تم التسليم';rr.deliveredAt=x.date;rr.paymentRecorded=true;rr.paymentInvoiceId=x.id;tx.objectStore('repairs').put(rr)}}else if(i.depositId){const p=products.find(z=>z.id===i.productId);if(p){const before=Number(p.stock);p.stock=Math.max(0,before-1);tx.objectStore('products').put(p);tx.objectStore('stockMoves').put({id:uid(),date:x.date,productId:p.id,product:p.name,qty:-1,before,after:p.stock,reason:'تسوية عربون / بيع',ref:x.id})}}else{const p=products.find(p=>p.id===i.id);if(p&&p.type!=='service'){const before=Number(p.stock);p.stock=Math.max(0,before-i.qty);tx.objectStore('products').put(p);tx.objectStore('stockMoves').put({id:uid(),date:x.date,productId:p.id,product:p.name,qty:-i.qty,before,after:p.stock,reason:'بيع',ref:x.id})}}}if(depositItem){const dep=deposits.find(z=>z.id===depositItem.depositId);dep.status='settled';dep.settledAt=x.date;dep.settlementSaleId=x.id;tx.objectStore('deposits').put(dep)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('فشل حفظ الفاتورة'));tx.onabort=()=>reject(tx.error||new Error('تم إلغاء الحفظ'))});await log('بيع',x);state.lastInvoice=x;clearCart();state.saleAccount='drawer';state.saleCustomer='';state.depositSettlementId='';toast('تم حفظ الفاتورة وتسجيل التحصيل بنجاح');render()}catch(e){console.error(e);toast(e.message||'فشل حفظ الفاتورة — لم يتم تغيير السلة')}}

function classifySale(x){let grossProduct=0,grossRepair=0,cogs=0;for(const i of (x.items||[])){const v=Number(i.price||0)*Number(i.qty||0);if(i.repairId)grossRepair+=v;else if(i.depositId){grossProduct+=Number(i.originalPrice||x.total||0);if(i.productId)cogs+=Number(i.cost||0)}else{grossProduct+=v;cogs+=Number(i.cost||0)*Number(i.qty||0)}}const gross=grossProduct+grossRepair,discount=Number(x.discount||0),factor=gross>0?Math.max(0,(gross-discount)/gross):1;return {product:grossProduct*factor,repair:grossRepair*factor,cogs:cogs*factor,discount}}
